(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-054"]={"sura":54,"name_ar":"القمر","name_en":"Al-Qamar","verses":55,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":55,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=5\" class=\"link\">54:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:5 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=5\" class=\"link\">54:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:5 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=5\" class=\"link\">54:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:5 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=5\" class=\"link\">54:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:5 ஐ பார்க்கவும்"},"5":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\nஅபூ வாகித் (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸ் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது; அதில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்-அள்ஹா மற்றும் அல்-ஃபித்ர் (பெருநாள் தொழுகைகளின்) போது ஸூரா காஃப் (அத்தியாயம் 50) மற்றும் இக்தரபத் அஸ்-ஸாஆ (அல்-கமர், அத்தியாயம் 54) ஆகியவற்றை ஓதுவார்கள் என்று கூறப்பட்டுள்ளது. நபி (ஸல்) அவர்கள் இந்த இரண்டு ஸூராக்களையும் பெரிய கூட்டங்கள் மற்றும் விசேஷ நிகழ்வுகளின் போது ஓதும் வழக்கத்தைக் கொண்டிருந்தார்கள். ஏனெனில், இந்த ஸூராக்களில் அல்லாஹ்வின் வாக்குறுதிகள், எச்சரிக்கைகள், படைப்பின் தொடக்கம், மறுவாழ்வு (உயிர்த்தெழுதல்), தவ்ஹீத், நபித்துவத்தை உறுதிப்படுத்துதல் போன்ற மிக முக்கியமான இலக்குகள் பற்றிய தகவல்கள் இடம்பெற்றுள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>மறுமை நேரம் நெருங்கிவிட்டது; சந்திரன் பிளந்துவிட்டது</strong><br />\r\n<br />\r\nமறுமை நேரம் நெருங்கிவிட்டதையும், இவ்வுலகின் முடிவும் அழிவும் மிக அண்மையில் இருப்பதையும் பற்றி அல்லாஹ் அறிவிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَعْجِلُوهُ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் கட்டளை வந்துவிட்டது, எனவே அதை அவசரப்படுத்தாதீர்கள்.)(<a href=\"qurandisp.php?sura=16&ayah=1\" class=\"link\">16:1</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">حِسَـبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَفْلَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّعْرِضُونَ</span><br />\r\n<br />\r\n(மனிதர்களுக்கு அவர்களது விசாரணை (நேரம்) நெருங்கிவிட்டது, ஆனால் அவர்களோ பாராமுகமாகப் புறக்கணித்துக் கொண்டிருக்கிறார்கள்.)(<a href=\"qurandisp.php?sura=21&ayah=1\" class=\"link\">21:1</a>)<br />\r\n<br />\r\n<strong>மறுமை நேரம் குறித்த ஹதீஸ்கள்</strong><br />\r\n<br />\r\nஇதே கருத்தில் பல ஹதீஸ்கள் உள்ளன. அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் பதிவு செய்துள்ளதாவது: அனஸ் (ரழி) அவர்கள் கூறினார்கள், ஒரு நாள் சூரியன் மறையவிருந்த நேரத்தில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் தோழர்களிடையே உரையாற்றினார்கள். அப்போது அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَقِيَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">مَضَى</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">بَقِيَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">يَوْمِكُمْ</span> <span class=\"quran-arabic-font text-success\">هذَا</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">مَضَى</span> <span class=\"quran-arabic-font text-success\">مِنْه</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவ்வுலகின் கடந்த காலத்துடன் ஒப்பிடும்போது, உங்கள் இன்றைய நாளில் எஞ்சியிருக்கும் நேரத்தைப் போன்ற ஒரு சிறிய காலமே தவிர இவ்வுலகில் இனி எஞ்சியிருக்கவில்லை.) \"அந்த நேரத்தில் மறையும் சூரியனின் ஒரு சிறிய பகுதியை மட்டுமே எங்களால் காண முடிந்தது\" என்று அனஸ் (ரழி) அவர்கள் கூறினார்கள். மேற்கூறிய ஹதீஸை உறுதிப்படுத்தும் விதமாக இமாம் அஹ்மத் ஒரு ஹதீஸைப் பதிவு செய்துள்ளார். அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறினார்கள்: \"அஸர் நேரத்திற்குப் பிறகு குஅய்கஆன் மலைக்கு மேலே சூரியன் இருந்தபோது நாங்கள் நபி (ஸல்) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَعْمَارُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَعْمَارِ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">مَضَى</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">بَقِيَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">مَضَى</span>»<br />\r\n<br />\r\n(கடந்த கால சமூகங்களுடன் ஒப்பிடும்போது உங்கள் ஆயுட்காலத்தில் எஞ்சியிருப்பது, இன்றைய நாளில் எஞ்சியிருக்கும் நேரத்தைப் போன்றதே ஆகும்.)\" இமாம் அஹ்மத் பதிவு செய்துள்ள மற்றொரு அறிவிப்பில்: ஸஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் கூறக் கேட்டதாகக் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">وَالسَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">هكَذَا</span>»<br />\r\n<br />\r\n(நானும் மறுமை நேரமும் இவ்வாறு அனுப்பப்பட்டுள்ளோம்) என்று கூறித் தமது நடுவிரலையும் ஆள்காட்டி விரலையும் சுட்டிக்காட்டினார்கள். இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரண்டு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: வஹ்ப் அஸ்-ஸுவாயீ (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">وَالسَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">كَهذِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هذِهِ،</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">كَادَتْ</span> <span class=\"quran-arabic-font text-success\">لَتَسْبِقُنِي</span>»<br />\r\n<br />\r\n(மறுமை நேரத்திற்கு மிக நெருக்கமாக நான் அனுப்பப்பட்டுள்ளேன்; இதுவும் இதுவும் (விரல்கள்) இருப்பதைப் போல, ஒன்று மற்றொன்றை முந்திவிடும் அளவுக்கு மிக நெருக்கமாக.) இந்த ஹதீஸை அறிவிக்கும்போது அல்-அஃமஷ் அவர்கள் தமது ஆள்காட்டி விரலையும் நடுவிரலையும் சேர்த்துக் காட்டினார்கள். இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அல்-அவ்ஸாஈ அவர்கள், இஸ்மாயீல் பின் உபைதுல்லாஹ் கூறியதாகக் கூறுகிறார்கள், \"அனஸ் பின் மாலிக் (ரழி) அவர்கள் அல்-வலீத் பின் அப்துல் மாலிக் என்பவரிடம் சென்றார்கள். அப்போது அவர், மறுமை நேரம் குறித்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அனஸ் (ரழி) கேட்டவற்றை வினவினார். அதற்கு அனஸ் (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَالسَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">كَهَاتَيْن</span>»<br />\r\n<br />\r\n(நீங்களும் மறுமை நேரமும் இந்த இரண்டு விரல்களைப் போல மிக நெருக்கமாக இருக்கிறீர்கள்.)'\" இந்த ஹதீஸை இமாம் அஹ்மத் மட்டுமே பதிவு செய்துள்ளார்கள். இந்த ஹதீஸ்களை உறுதிப்படுத்தும் ஒரு சான்று ஸஹீஹ் புகாரியில் உள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பெயர்களில் 'அல்-ஹாஷிர்' (ஒன்றுதிரட்டுபவர்) என்பதும் ஒன்று; அதாவது மறுமை நாளில் முதலில் அவர்கள் எழுப்பப்பட்டு ஒன்றுதிரட்டப்படுவார்கள், அதன் பின்னரே மக்கள் அனைவரும் ஒன்றுதிரட்டப்படுவார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span><br />\r\n<br />\r\n(சந்திரனும் பிளந்துவிட்டது.) ஆதாரப்பூர்வமான முதவாதிர் ஹதீஸ்களின்படி, இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் வாழ்நாளிலேயே நிகழ்ந்தது. நபி (ஸல்) அவர்களுக்கு அல்லாஹ் வழங்கிய தெளிவான அற்புதங்களில் (முஃஜிஸாத்துகளில்) இதுவும் ஒன்று என்பதில் அறிஞர்கள் ஏகோபித்த கருத்தைக் கொண்டுள்ளனர்.<br />\r\n<br />\r\n<strong>சந்திரன் பிளந்தது குறித்த ஹதீஸ்கள்</strong><br />\r\n<br />\r\n<strong>அனஸ் பின் மாலிக் (ரழி) அவர்களின் அறிவிப்பு</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"மக்கா மக்கள் நபி (ஸல்) அவர்களிடம் ஓர் அற்புதத்தைக் காட்டுமாறு கோரினார்கள். அப்போது மக்காவில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span><br />\r\n<br />\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது.)\" இந்த ஹதீஸை இமாம் முஸ்லிமும் பதிவு செய்துள்ளார். இமாம் புகாரி பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"மக்கா மக்கள் ஒரு அற்புதத்தைக் காட்டுமாறு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்டபோது, அவர்கள் சந்திரனை இரண்டு துண்டுகளாகப் பிளந்து காட்டினார்கள். அவ்விரு துண்டுகளுக்கிடையில் ஹிரா மலையை அவர்கள் காணும் வரை அது பிளந்திருந்தது.\" இந்த ஹதீஸ் பல்வேறு அறிவிப்பாளர் தொடர்களின் வழியாக இரண்டு ஸஹீஹ் நூல்களிலும் பதிவாகியுள்ளது.<br />\r\n<br />\r\n<strong>ஜுபைர் பின் முத்இம் (ரழி) அவர்களின் அறிவிப்பு</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் நபி (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது. சந்திரனின் ஒரு பகுதி ஒரு மலையின் மீதும், மறு பகுதி மற்றொரு மலையின் மீதும் தென்பட்டது. உடனே அவர்கள் (குறைஷியர்), 'முஹம்மது நமக்குச் சூனியம் செய்துவிட்டார்' என்று கூறினார்கள். பிறகு அவர்கள், 'அவர் நமக்குச் சூனியம் செய்திருந்தாலும், எல்லா மக்களுக்கும் அவரால் சூனியம் செய்ய முடியாது (ஆகவே இது உண்மையான நிகழ்வே)' என்று பேசிக்கொண்டனர்.\" இந்த அறிவிப்பாளர் தொடருடன் இமாம் அஹ்மத் மட்டுமே இதைத் தொகுத்துள்ளார். அல்-பைஹகி அவர்கள் தனது 'அத்-தலாஇல்' நூலில் வேறொரு தொடரின் வழியாக இதே போன்ற ஒரு ஹதீஸைப் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\n<strong>அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பு</strong><br />\r\n<br />\r\nஇமாம் புகாரி பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"நபி (ஸல்) அவர்களின் காலத்தில் சந்திரன் பிளந்தது.\" இமாம் புகாரியும் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இப்னு ஜரீர் பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் அல்லாஹ்வின் பின்வரும் வசனத்திற்கு விளக்கம் அளிக்கையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span> - <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span> <span class=\"quran-arabic-font text-success\">يُعْرِضُواْ</span> <span class=\"quran-arabic-font text-success\">وَيَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَمِرٌّ</span><br />\r\n<br />\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது. அவர்கள் ஓர் அத்தாட்சியைக் கண்டால், அதைப் புறக்கணித்துவிட்டு, 'இது தொடர்ச்சியான சூனியம்' என்று கூறுகிறார்கள்.) \"இது ஹிஜ்ரத்திற்கு முன்பே நிகழ்ந்தது; சந்திரன் பிளந்ததை அவர்கள் இரண்டு துண்டுகளாகக் கண்டார்கள்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<strong>அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களின் அறிவிப்பு</strong><br />\r\n<br />\r\nஅல்-பைஹகி பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அல்லாஹ்வின் வசனமான:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اقْتَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">وَانشَقَّ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرُ</span><br />\r\n<br />\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது.) என்பதற்கு விளக்கம் அளிக்கையில், \"இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தபோது நிகழ்ந்தது. ஒரு பகுதி மலையின் முன்புறமும், மறுபகுதி அதன் மறுபுறமும் இருந்தது. அப்போது நபி (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللْهُمَّ</span> <span class=\"quran-arabic-font text-success\">اشْهَد</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! நீயே சாட்சியாக இரு) என்று கூறினார்கள்\" எனக் குறிப்பிட்டார்கள். இது இமாம் முஸ்லிம் மற்றும் திர்மிதி ஆகியோரால் தொகுக்கப்பட்ட அறிவிப்பாகும். இமாம் திர்மிதி இது 'ஹஸன் ஸஹீஹ்' என்று கூறியுள்ளார்.<br />\r\n<br />\r\n<strong>அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களின் அறிவிப்பு</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது; மக்கள் அதன் இரண்டு பகுதிகளையும் பார்த்தனர். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اشْهَدُوا</span>»<br />\r\n<br />\r\n(சாட்சிகளாக இருங்கள்) என்று கூறினார்கள்.\" இந்த ஹதீஸை புகாரியும் முஸ்லிமும் பதிவு செய்துள்ளனர். இப்னு ஜரீர் பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள், \"சந்திரன் பிளந்திருந்தபோது அதன் இரண்டு பகுதிகளுக்கு இடையில் மலையை நான் கண்டேன்.\" இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: \"சந்திரன் பிளந்தபோது அதன் இரண்டு துண்டுகளுக்கு இடையில் நான் மலையைப் பார்த்தேன்\" என்று அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்.<br />\r\n<br />\r\n<strong>இணைவைப்பாளர்களின் பிடிவாதம்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span><br />\r\n<br />\r\n(அவர்கள் ஓர் அத்தாட்சியைக் கண்டால்), அதாவது ஒரு தெளிவான ஆதாரம், சான்று அல்லது அற்புதத்தைக் கண்டால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُعْرِضُواْ</span><br />\r\n<br />\r\n(அவர்கள் புறக்கணிக்கிறார்கள்), அவர்கள் அதனை நம்புவதில்லை. மாறாக, அதனை அலட்சியப்படுத்திப் புறக்கணிக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سِحْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَمِرٌّ</span><br />\r\n<br />\r\n(மேலும், 'இது தொடர்ச்சியான சூனியம்' என்று கூறுகிறார்கள்.) \"நாங்கள் பார்த்த இந்த அத்தாட்சி எங்கள் மீது ஏவப்பட்ட சூனியம்\" என்று அவர்கள் கூறுகிறார்கள். முஜாஹித், கதாதா மற்றும் பலரின் கூற்றுப்படி 'முஸ்தமிர்' என்றால் 'விரைவில் மறைந்துவிடக்கூடியது' என்று பொருளாகும். சந்திரன் பிளந்தது என்பது ஒரு மாயை, அது விரைவில் மறைந்துவிடும் என்று குறைஷியர் கூறினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعُواْ</span> <span class=\"quran-arabic-font text-success\">أَهْوَآءَهُمْ</span><br />\r\n<br />\r\n(அவர்கள் உண்மையைப் பொய்ப்பித்தார்கள், மேலும் தங்கள் மனோ இச்சைகளைப் பின்பற்றினார்கள்.) தங்களுக்கு உண்மை வந்தபோது அவர்கள் அதனை நிராகரித்துவிட்டு, தங்கள் ஆசைகளும் விருப்பங்களும் தூண்டிய அறியாமை மற்றும் முட்டாள்தனத்தைப் பின்பற்றினார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">أَمْرٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِرٌّ</span><br />\r\n<br />\r\n(ஒவ்வொரு காரியமும் நிலைபெறும்.) கதாதாவின் கருத்துப்படி, நற்செயல்கள் அதனைச் செய்பவர்களை நன்மையின் பக்கமும், தீய செயல்கள் அதனைச் செய்பவர்களைத் தீமையின் பக்கமும் கொண்டு செல்லும் என்பதாகும். இப்னு ஜுரைஜ் அவர்கள், \"ஒவ்வொரு காரியமும் அதன் மக்களுக்குத் தகுந்தவாறு அமையும்\" என்று கூறுகிறார்கள். முஜாஹித் அவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">أَمْرٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِرٌّ</span><br />\r\n<br />\r\n(ஒவ்வொரு காரியமும் நிலைபெறும்) என்பதற்கு \"மறுமை நாளில்\" என்று விளக்கம் அளிக்கிறார்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَاءَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَنْبَاءِ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்களிடம் செய்திகள் வந்துள்ளன); இந்த குர்ஆனில், தங்கள் தூதர்களை நிராகரித்த முந்தைய சமூகங்களின் வரலாறுகளும், அவர்களுக்கு ஏற்பட்ட வேதனை, தண்டனை மற்றும் சோதனைகள் குறித்த செய்திகளும் வந்துள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مُزْدَجَرٌ</span><br />\r\n<br />\r\n(அதில் 'முஸ்தஜர்' உள்ளது), அதாவது அவர்கள் இணைவைப்பதிலிருந்தும், பிடிவாதமாக நிராகரிப்பதிலிருந்தும் அவர்களைத் தடுக்கக்கூடிய எச்சரிக்கைகளும் படிப்பினைகளும் அதில் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حِكْمَةٌ</span> <span class=\"quran-arabic-font text-success\">بَـلِغَةٌ</span><br />\r\n<br />\r\n(முழுமையான ஞானம்,) அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான் என்பதில் அவனது ஞானம் முழுமையானது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">تُغْنِ</span> <span class=\"quran-arabic-font text-success\">النُّذُرُ</span><br />\r\n<br />\r\n(ஆனால் எச்சரிக்கை செய்பவர்கள் அவர்களுக்குப் பயனளிக்க மாட்டார்கள்.) அல்லாஹ் யாருக்குத் துர்பாக்கியத்தை விதித்து, அவர்களின் இதயங்களை முத்திரையிட்டுவிட்டானோ, அவர்களுக்கு எச்சரிக்கைகள் யாதொரு பயனும் அளிக்காது. அல்லாஹ்வுக்குப் பிறகு இத்தகையோருக்கு யார் நேர்வழி காட்ட முடியும்? இந்த வசனம் அல்லாஹ்வின் பிற கூற்றுகளைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">فَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الْحُجَّةُ</span> <span class=\"quran-arabic-font text-success\">الْبَـلِغَةُ</span> <span class=\"quran-arabic-font text-success\">فَلَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">لَهَدَاكُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span><br />\r\n<br />\r\n(கூறுவீராக: \"அல்லாஹ்விடமே முழுமையான ஆதாரமும் வாதமும் உள்ளது; அவன் நாடியிருந்தால் உங்கள் அனைவரையும் நேர்வழியில் செலுத்தியிருப்பான்.\")(<a href=\"qurandisp.php?sura=6&ayah=149\" class=\"link\">6:149</a>) மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تُغْنِى</span> <span class=\"quran-arabic-font text-success\">الآيَـتُ</span> <span class=\"quran-arabic-font text-success\">وَالنُّذُرُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قَوْمٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n(ஆனால் நம்பிக்கை கொள்ளாத சமூகத்திற்கு அத்தாட்சிகளும், எச்சரிக்கை செய்பவர்களும் பயனளிக்க மாட்டார்கள்.)(<a href=\"qurandisp.php?sura=10&ayah=101\" class=\"link\">10:101</a>)<br />\r\n<br />\r\n<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nஅபூ வாகித் (ரழி) அவர்கள் அறிவிக்கும் ஹதீஸ் ஏற்கனவே குறிப்பிடப்பட்டுள்ளது; அதில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அல்-அள்ஹா மற்றும் அல்-ஃபித்ர் (பெருநாள் தொழுகைகளின்) போது ஸூரா காஃப் (அத்தியாயம் 50) மற்றும் இக்தரபத் அஸ்-ஸாஆ (அல்-கமர், அத்தியாயம் 54) ஆகியவற்றை ஓதுவார்கள் என்று கூறப்பட்டுள்ளது. நபி (ஸல்) அவர்கள் இந்த இரண்டு ஸூராக்களையும் பெரிய கூட்டங்கள் மற்றும் விசேஷ நிகழ்வுகளின் போது ஓதும் வழக்கத்தைக் கொண்டிருந்தார்கள். ஏனெனில், இந்த ஸூராக்களில் அல்லாஹ்வின் வாக்குறுதிகள், எச்சரிக்கைகள், படைப்பின் தொடக்கம், மறுவாழ்வு (உயிர்த்தெழுதல்), தவ்ஹீத், நபித்துவத்தை உறுதிப்படுத்துதல் போன்ற மிக முக்கியமான இலக்குகள் பற்றிய தகவல்கள் இடம்பெற்றுள்ளன.\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nமறுமை நேரம் நெருங்கிவிட்டது; சந்திரன் பிளந்துவிட்டது\n\r\n\n\r\nமறுமை நேரம் நெருங்கிவிட்டதையும், இவ்வுலகின் முடிவும் அழிவும் மிக அண்மையில் இருப்பதையும் பற்றி அல்லாஹ் அறிவிக்கிறான்:\n\r\n\n\r\nأَتَى أَمْرُ اللَّهِ فَلاَ تَسْتَعْجِلُوهُ\n\r\n\n\r\n(அல்லாஹ்வின் கட்டளை வந்துவிட்டது, எனவே அதை அவசரப்படுத்தாதீர்கள்.)(16:1),\n\r\n\n\r\nاقْتَرَبَ لِلنَّاسِ حِسَـبُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ\n\r\n\n\r\n(மனிதர்களுக்கு அவர்களது விசாரணை (நேரம்) நெருங்கிவிட்டது, ஆனால் அவர்களோ பாராமுகமாகப் புறக்கணித்துக் கொண்டிருக்கிறார்கள்.)(21:1)\n\r\n\n\r\nமறுமை நேரம் குறித்த ஹதீஸ்கள்\n\r\n\n\r\nஇதே கருத்தில் பல ஹதீஸ்கள் உள்ளன. அல்-ஹாஃபிழ் அபூ பக்ர் அல்-பஸ்ஸார் பதிவு செய்துள்ளதாவது: அனஸ் (ரழி) அவர்கள் கூறினார்கள், ஒரு நாள் சூரியன் மறையவிருந்த நேரத்தில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தம் தோழர்களிடையே உரையாற்றினார்கள். அப்போது அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَالَّذِي نَفْسِي بِيَدِهِ مَا بَقِيَ مِنَ الدُّنْيَا فِيمَا مَضَى مِنْهَا إِلَّا كَمَا بَقِيَ مِنْ يَوْمِكُمْ هذَا فِيمَا مَضَى مِنْه»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! இவ்வுலகின் கடந்த காலத்துடன் ஒப்பிடும்போது, உங்கள் இன்றைய நாளில் எஞ்சியிருக்கும் நேரத்தைப் போன்ற ஒரு சிறிய காலமே தவிர இவ்வுலகில் இனி எஞ்சியிருக்கவில்லை.) \"அந்த நேரத்தில் மறையும் சூரியனின் ஒரு சிறிய பகுதியை மட்டுமே எங்களால் காண முடிந்தது\" என்று அனஸ் (ரழி) அவர்கள் கூறினார்கள். மேற்கூறிய ஹதீஸை உறுதிப்படுத்தும் விதமாக இமாம் அஹ்மத் ஒரு ஹதீஸைப் பதிவு செய்துள்ளார். அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறினார்கள்: \"அஸர் நேரத்திற்குப் பிறகு குஅய்கஆன் மலைக்கு மேலே சூரியன் இருந்தபோது நாங்கள் நபி (ஸல்) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا أَعْمَارُكُمْ فِي أَعْمَارِ مَنْ مَضَى إِلَّا كَمَا بَقِيَ مِنَ النَّهَارِ فِيمَا مَضَى»\n\r\n\n\r\n(கடந்த கால சமூகங்களுடன் ஒப்பிடும்போது உங்கள் ஆயுட்காலத்தில் எஞ்சியிருப்பது, இன்றைய நாளில் எஞ்சியிருக்கும் நேரத்தைப் போன்றதே ஆகும்.)\" இமாம் அஹ்மத் பதிவு செய்துள்ள மற்றொரு அறிவிப்பில்: ஸஹ்ல் பின் ஸஅத் (ரழி) அவர்கள் கூறக் கேட்டதாகக் கூறினார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,\n\r\n\n\r\n«بُعِثْتُ أَنَا وَالسَّاعَةُ هكَذَا»\n\r\n\n\r\n(நானும் மறுமை நேரமும் இவ்வாறு அனுப்பப்பட்டுள்ளோம்) என்று கூறித் தமது நடுவிரலையும் ஆள்காட்டி விரலையும் சுட்டிக்காட்டினார்கள். இந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரண்டு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: வஹ்ப் அஸ்-ஸுவாயீ (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«بُعِثْتُ أَنَا وَالسَّاعَةُ كَهذِهِ مِنْ هذِهِ، إِنْ كَادَتْ لَتَسْبِقُنِي»\n\r\n\n\r\n(மறுமை நேரத்திற்கு மிக நெருக்கமாக நான் அனுப்பப்பட்டுள்ளேன்; இதுவும் இதுவும் (விரல்கள்) இருப்பதைப் போல, ஒன்று மற்றொன்றை முந்திவிடும் அளவுக்கு மிக நெருக்கமாக.) இந்த ஹதீஸை அறிவிக்கும்போது அல்-அஃமஷ் அவர்கள் தமது ஆள்காட்டி விரலையும் நடுவிரலையும் சேர்த்துக் காட்டினார்கள். இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அல்-அவ்ஸாஈ அவர்கள், இஸ்மாயீல் பின் உபைதுல்லாஹ் கூறியதாகக் கூறுகிறார்கள், \"அனஸ் பின் மாலிக் (ரழி) அவர்கள் அல்-வலீத் பின் அப்துல் மாலிக் என்பவரிடம் சென்றார்கள். அப்போது அவர், மறுமை நேரம் குறித்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அனஸ் (ரழி) கேட்டவற்றை வினவினார். அதற்கு அனஸ் (ரழி) அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டேன்:\n\r\n\n\r\n«أَنْتُمْ وَالسَّاعَةُ كَهَاتَيْن»\n\r\n\n\r\n(நீங்களும் மறுமை நேரமும் இந்த இரண்டு விரல்களைப் போல மிக நெருக்கமாக இருக்கிறீர்கள்.)'\" இந்த ஹதீஸை இமாம் அஹ்மத் மட்டுமே பதிவு செய்துள்ளார்கள். இந்த ஹதீஸ்களை உறுதிப்படுத்தும் ஒரு சான்று ஸஹீஹ் புகாரியில் உள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் பெயர்களில் 'அல்-ஹாஷிர்' (ஒன்றுதிரட்டுபவர்) என்பதும் ஒன்று; அதாவது மறுமை நாளில் முதலில் அவர்கள் எழுப்பப்பட்டு ஒன்றுதிரட்டப்படுவார்கள், அதன் பின்னரே மக்கள் அனைவரும் ஒன்றுதிரட்டப்படுவார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَانشَقَّ الْقَمَرُ\n\r\n\n\r\n(சந்திரனும் பிளந்துவிட்டது.) ஆதாரப்பூர்வமான முதவாதிர் ஹதீஸ்களின்படி, இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் வாழ்நாளிலேயே நிகழ்ந்தது. நபி (ஸல்) அவர்களுக்கு அல்லாஹ் வழங்கிய தெளிவான அற்புதங்களில் (முஃஜிஸாத்துகளில்) இதுவும் ஒன்று என்பதில் அறிஞர்கள் ஏகோபித்த கருத்தைக் கொண்டுள்ளனர்.\n\r\n\n\r\nசந்திரன் பிளந்தது குறித்த ஹதீஸ்கள்\n\r\n\n\r\nஅனஸ் பின் மாலிக் (ரழி) அவர்களின் அறிவிப்பு\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"மக்கா மக்கள் நபி (ஸல்) அவர்களிடம் ஓர் அற்புதத்தைக் காட்டுமாறு கோரினார்கள். அப்போது மக்காவில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nاقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ\n\r\n\n\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது.)\" இந்த ஹதீஸை இமாம் முஸ்லிமும் பதிவு செய்துள்ளார். இமாம் புகாரி பதிவு செய்துள்ளதாவது: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள், \"மக்கா மக்கள் ஒரு அற்புதத்தைக் காட்டுமாறு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்டபோது, அவர்கள் சந்திரனை இரண்டு துண்டுகளாகப் பிளந்து காட்டினார்கள். அவ்விரு துண்டுகளுக்கிடையில் ஹிரா மலையை அவர்கள் காணும் வரை அது பிளந்திருந்தது.\" இந்த ஹதீஸ் பல்வேறு அறிவிப்பாளர் தொடர்களின் வழியாக இரண்டு ஸஹீஹ் நூல்களிலும் பதிவாகியுள்ளது.\n\r\n\n\r\nஜுபைர் பின் முத்இம் (ரழி) அவர்களின் அறிவிப்பு\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: ஜுபைர் பின் முத்இம் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் நபி (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது. சந்திரனின் ஒரு பகுதி ஒரு மலையின் மீதும், மறு பகுதி மற்றொரு மலையின் மீதும் தென்பட்டது. உடனே அவர்கள் (குறைஷியர்), 'முஹம்மது நமக்குச் சூனியம் செய்துவிட்டார்' என்று கூறினார்கள். பிறகு அவர்கள், 'அவர் நமக்குச் சூனியம் செய்திருந்தாலும், எல்லா மக்களுக்கும் அவரால் சூனியம் செய்ய முடியாது (ஆகவே இது உண்மையான நிகழ்வே)' என்று பேசிக்கொண்டனர்.\" இந்த அறிவிப்பாளர் தொடருடன் இமாம் அஹ்மத் மட்டுமே இதைத் தொகுத்துள்ளார். அல்-பைஹகி அவர்கள் தனது 'அத்-தலாஇல்' நூலில் வேறொரு தொடரின் வழியாக இதே போன்ற ஒரு ஹதீஸைப் பதிவு செய்துள்ளார்.\n\r\n\n\r\nஅப்துல்லாஹ் பின் அப்பாஸ் (ரழி) அவர்களின் அறிவிப்பு\n\r\n\n\r\nஇமாம் புகாரி பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"நபி (ஸல்) அவர்களின் காலத்தில் சந்திரன் பிளந்தது.\" இமாம் புகாரியும் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். இப்னு ஜரீர் பதிவு செய்துள்ளதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் அல்லாஹ்வின் பின்வரும் வசனத்திற்கு விளக்கம் அளிக்கையில்:\n\r\n\n\r\nاقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ - وَإِن يَرَوْاْ ءَايَةً يُعْرِضُواْ وَيَقُولُواْ سِحْرٌ مُّسْتَمِرٌّ\n\r\n\n\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது. அவர்கள் ஓர் அத்தாட்சியைக் கண்டால், அதைப் புறக்கணித்துவிட்டு, 'இது தொடர்ச்சியான சூனியம்' என்று கூறுகிறார்கள்.) \"இது ஹிஜ்ரத்திற்கு முன்பே நிகழ்ந்தது; சந்திரன் பிளந்ததை அவர்கள் இரண்டு துண்டுகளாகக் கண்டார்கள்\" என்று கூறினார்கள்.\n\r\n\n\r\nஅப்துல்லாஹ் பின் உமர் (ரழி) அவர்களின் அறிவிப்பு\n\r\n\n\r\nஅல்-பைஹகி பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அல்லாஹ்வின் வசனமான:\n\r\n\n\r\nاقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ\n\r\n\n\r\n((மறுமை) நேரம் நெருங்கிவிட்டது, சந்திரனும் பிளந்துவிட்டது.) என்பதற்கு விளக்கம் அளிக்கையில், \"இது அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தபோது நிகழ்ந்தது. ஒரு பகுதி மலையின் முன்புறமும், மறுபகுதி அதன் மறுபுறமும் இருந்தது. அப்போது நபி (ஸல்) அவர்கள்,\n\r\n\n\r\n«اللْهُمَّ اشْهَد»\n\r\n\n\r\n(யா அல்லாஹ்! நீயே சாட்சியாக இரு) என்று கூறினார்கள்\" எனக் குறிப்பிட்டார்கள். இது இமாம் முஸ்லிம் மற்றும் திர்மிதி ஆகியோரால் தொகுக்கப்பட்ட அறிவிப்பாகும். இமாம் திர்மிதி இது 'ஹஸன் ஸஹீஹ்' என்று கூறியுள்ளார்.\n\r\n\n\r\nஅப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்களின் அறிவிப்பு\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில் சந்திரன் இரண்டு துண்டுகளாகப் பிளந்தது; மக்கள் அதன் இரண்டு பகுதிகளையும் பார்த்தனர். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்,\n\r\n\n\r\n«اشْهَدُوا»\n\r\n\n\r\n(சாட்சிகளாக இருங்கள்) என்று கூறினார்கள்.\" இந்த ஹதீஸை புகாரியும் முஸ்லிமும் பதிவு செய்துள்ளனர். இப்னு ஜரீர் பதிவு செய்துள்ளதாவது: அப்துல்லாஹ் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள், \"சந்திரன் பிளந்திருந்தபோது அதன் இரண்டு பகுதிகளுக்கு இடையில் மலையை நான் கண்டேன்.\" இமாம் அஹ்மத் பதிவு செய்துள்ளதாவது: \"சந்திரன் பிளந்தபோது அதன் இரண்டு துண்டுகளுக்கு இடையில் நான் மலையைப் பார்த்தேன்\" என்று அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள்.\n\r\n\n\r\nஇணைவைப்பாளர்களின் பிடிவாதம்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَإِن يَرَوْاْ ءَايَةً\n\r\n\n\r\n(அவர்கள் ஓர் அத்தாட்சியைக் கண்டால்), அதாவது ஒரு தெளிவான ஆதாரம், சான்று அல்லது அற்புதத்தைக் கண்டால்,\n\r\n\n\r\nيُعْرِضُواْ\n\r\n\n\r\n(அவர்கள் புறக்கணிக்கிறார்கள்), அவர்கள் அதனை நம்புவதில்லை. மாறாக, அதனை அலட்சியப்படுத்திப் புறக்கணிக்கிறார்கள்.\n\r\n\n\r\nوَيَقُولُواْ سِحْرٌ مُّسْتَمِرٌّ\n\r\n\n\r\n(மேலும், 'இது தொடர்ச்சியான சூனியம்' என்று கூறுகிறார்கள்.) \"நாங்கள் பார்த்த இந்த அத்தாட்சி எங்கள் மீது ஏவப்பட்ட சூனியம்\" என்று அவர்கள் கூறுகிறார்கள். முஜாஹித், கதாதா மற்றும் பலரின் கூற்றுப்படி 'முஸ்தமிர்' என்றால் 'விரைவில் மறைந்துவிடக்கூடியது' என்று பொருளாகும். சந்திரன் பிளந்தது என்பது ஒரு மாயை, அது விரைவில் மறைந்துவிடும் என்று குறைஷியர் கூறினர்.\n\r\n\n\r\nوَكَذَّبُواْ وَاتَّبَعُواْ أَهْوَآءَهُمْ\n\r\n\n\r\n(அவர்கள் உண்மையைப் பொய்ப்பித்தார்கள், மேலும் தங்கள் மனோ இச்சைகளைப் பின்பற்றினார்கள்.) தங்களுக்கு உண்மை வந்தபோது அவர்கள் அதனை நிராகரித்துவிட்டு, தங்கள் ஆசைகளும் விருப்பங்களும் தூண்டிய அறியாமை மற்றும் முட்டாள்தனத்தைப் பின்பற்றினார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَكُلُّ أَمْرٍ مُّسْتَقِرٌّ\n\r\n\n\r\n(ஒவ்வொரு காரியமும் நிலைபெறும்.) கதாதாவின் கருத்துப்படி, நற்செயல்கள் அதனைச் செய்பவர்களை நன்மையின் பக்கமும், தீய செயல்கள் அதனைச் செய்பவர்களைத் தீமையின் பக்கமும் கொண்டு செல்லும் என்பதாகும். இப்னு ஜுரைஜ் அவர்கள், \"ஒவ்வொரு காரியமும் அதன் மக்களுக்குத் தகுந்தவாறு அமையும்\" என்று கூறுகிறார்கள். முஜாஹித் அவர்கள்,\n\r\n\n\r\nوَكُلُّ أَمْرٍ مُّسْتَقِرٌّ\n\r\n\n\r\n(ஒவ்வொரு காரியமும் நிலைபெறும்) என்பதற்கு \"மறுமை நாளில்\" என்று விளக்கம் அளிக்கிறார்கள். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلَقَدْ جَاءَهُمْ مِنَ الْأَنْبَاءِ\n\r\n\n\r\n(நிச்சயமாக அவர்களிடம் செய்திகள் வந்துள்ளன); இந்த குர்ஆனில், தங்கள் தூதர்களை நிராகரித்த முந்தைய சமூகங்களின் வரலாறுகளும், அவர்களுக்கு ஏற்பட்ட வேதனை, தண்டனை மற்றும் சோதனைகள் குறித்த செய்திகளும் வந்துள்ளன.\n\r\n\n\r\nمَا فِيهِ مُزْدَجَرٌ\n\r\n\n\r\n(அதில் 'முஸ்தஜர்' உள்ளது), அதாவது அவர்கள் இணைவைப்பதிலிருந்தும், பிடிவாதமாக நிராகரிப்பதிலிருந்தும் அவர்களைத் தடுக்கக்கூடிய எச்சரிக்கைகளும் படிப்பினைகளும் அதில் உள்ளன.\n\r\n\n\r\nحِكْمَةٌ بَـلِغَةٌ\n\r\n\n\r\n(முழுமையான ஞானம்,) அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான், தான் நாடியவர்களை வழிகேட்டில் விடுகிறான் என்பதில் அவனது ஞானம் முழுமையானது.\n\r\n\n\r\nفَمَا تُغْنِ النُّذُرُ\n\r\n\n\r\n(ஆனால் எச்சரிக்கை செய்பவர்கள் அவர்களுக்குப் பயனளிக்க மாட்டார்கள்.) அல்லாஹ் யாருக்குத் துர்பாக்கியத்தை விதித்து, அவர்களின் இதயங்களை முத்திரையிட்டுவிட்டானோ, அவர்களுக்கு எச்சரிக்கைகள் யாதொரு பயனும் அளிக்காது. அல்லாஹ்வுக்குப் பிறகு இத்தகையோருக்கு யார் நேர்வழி காட்ட முடியும்? இந்த வசனம் அல்லாஹ்வின் பிற கூற்றுகளைப் போன்றதாகும்:\n\r\n\n\r\nقُلْ فَلِلَّهِ الْحُجَّةُ الْبَـلِغَةُ فَلَوْ شَآءَ لَهَدَاكُمْ أَجْمَعِينَ\n\r\n\n\r\n(கூறுவீராக: \"அல்லாஹ்விடமே முழுமையான ஆதாரமும் வாதமும் உள்ளது; அவன் நாடியிருந்தால் உங்கள் அனைவரையும் நேர்வழியில் செலுத்தியிருப்பான்.\")(6:149) மேலும்,\n\r\n\n\r\nوَمَا تُغْنِى الآيَـتُ وَالنُّذُرُ عَن قَوْمٍ لاَّ يُؤْمِنُونَ\n\r\n\n\r\n(ஆனால் நம்பிக்கை கொள்ளாத சமூகத்திற்கு அத்தாட்சிகளும், எச்சரிக்கை செய்பவர்களும் பயனளிக்க மாட்டார்கள்.)(10:101)"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=8\" class=\"link\">54:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=8\" class=\"link\">54:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>மறுமை நாளில் நிராகரிப்பாளர்கள் சந்திக்கும் பயங்கரமான முடிவு</strong><br />\r\n<br />\r\nஉயர்வான அல்லாஹ் கூறுகிறான்: 'முஹம்மதே (ஸல்)! ஓர் அற்புதத்தைக் காணும்போது அதனை மறுத்து, \"இது தொடர்ச்சியான சூனியம்\" என்று கூறும் இந்த மக்களிடமிருந்து நீங்கள் விலகி இருங்கள்.' <span class=\"quran-arabic-font text-success\">﴾فَتَوَلَّ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ﴿</span> அவர்களிடமிருந்து விலகி (அந்த நாளுக்காகக்) காத்திருங்கள்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُ</span> <span class=\"quran-arabic-font text-success\">الدَّاعِ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">نُّكُرٍ﴿</span><br />\r\n<br />\r\n(அழைப்பவர் (அவர்களை) ஒரு பயங்கரமான விஷயத்திற்கு அழைக்கும் நாள்.) அதாவது, கூலி வழங்கப்படுவதற்கும், அந்த நாள் கொண்டு வரும் துன்பங்கள், திகில்கள் மற்றும் மாபெரும் கஷ்டங்களுக்கும் (அழைப்பார்), <span class=\"quran-arabic-font text-success\">﴾خُشَّعًا</span> <span class=\"quran-arabic-font text-success\">أَبْصَارُهُمْ﴿</span><br />\r\n<br />\r\n(தாழ்ந்த பார்வைகளுடன்), அவர்களின் கண்கள் இழிவினால் மூடப்பட்டிருக்கும், <span class=\"quran-arabic-font text-success\">﴾يَخْرُجُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَجْدَاثِ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">جَرَادٌ</span> <span class=\"quran-arabic-font text-success\">مُّنتَشِرٌ﴿</span><br />\r\n<br />\r\n(அவர்கள் பரவிக்கிடக்கும் வெட்டுக்கிளிகளைப் போல் தங்களின் மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) வெளியேறுவார்கள்.) அழைப்பவருக்குப் பதிலளிக்கும் விதமாக, நாலாபுறமும் பரவிக்கிடக்கும் வெட்டுக்கிளிக் கூட்டங்களைப் போல, அவர்கள் விசாரணை நடைபெறும் இடத்தை நோக்கி மிகுந்த வேகத்துடனும் கூட்டமாகவும் திரள்வார்கள். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾مُهْطِعِينَ﴿</span><br />\r\n<br />\r\n(விரைந்து செல்பவர்களாக), அதாவது மிக விரைவாக, <span class=\"quran-arabic-font text-success\">﴾إِلَى</span> <span class=\"quran-arabic-font text-success\">الدَّاعِ﴿</span><br />\r\n<br />\r\n(அழைப்பவரை நோக்கி), அவர்களால் தயங்கவோ அல்லது வேகத்தைக் குறைக்கவோ முடியாது, <span class=\"quran-arabic-font text-success\">﴾يَقُولُ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرُونَ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">يَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عَسِرٌ﴿</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் கூறுவார்கள்: \"இது ஒரு கடினமான நாள்.\") அதாவது, \"இது ஒரு கடினமான, பயங்கரமான, அச்சமூட்டும் மற்றும் வேதனைமிக்க நாள்.\" <span class=\"quran-arabic-font text-success\">﴾فَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عَسِيرٌ</span> - <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அந்த நாள் ஒரு கடினமான நாளாகும்; அது நிராகரிப்பாளர்களுக்கு எளியதல்ல.) (<a href=\"qurandisp.php?sura=74&ayah=9\" class=\"link\">74:9</a>-10)<br />\r\n<br />","text":"மறுமை நாளில் நிராகரிப்பாளர்கள் சந்திக்கும் பயங்கரமான முடிவு\n\r\n\n\r\nஉயர்வான அல்லாஹ் கூறுகிறான்: 'முஹம்மதே (ஸல்)! ஓர் அற்புதத்தைக் காணும்போது அதனை மறுத்து, \"இது தொடர்ச்சியான சூனியம்\" என்று கூறும் இந்த மக்களிடமிருந்து நீங்கள் விலகி இருங்கள்.' ﴾فَتَوَلَّ عَنْهُمْ﴿ அவர்களிடமிருந்து விலகி (அந்த நாளுக்காகக்) காத்திருங்கள்: ﴾يَوْمَ يَدْعُ الدَّاعِ إِلَى شَيْءٍ نُّكُرٍ﴿\n\r\n\n\r\n(அழைப்பவர் (அவர்களை) ஒரு பயங்கரமான விஷயத்திற்கு அழைக்கும் நாள்.) அதாவது, கூலி வழங்கப்படுவதற்கும், அந்த நாள் கொண்டு வரும் துன்பங்கள், திகில்கள் மற்றும் மாபெரும் கஷ்டங்களுக்கும் (அழைப்பார்), ﴾خُشَّعًا أَبْصَارُهُمْ﴿\n\r\n\n\r\n(தாழ்ந்த பார்வைகளுடன்), அவர்களின் கண்கள் இழிவினால் மூடப்பட்டிருக்கும், ﴾يَخْرُجُونَ مِنَ الْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ﴿\n\r\n\n\r\n(அவர்கள் பரவிக்கிடக்கும் வெட்டுக்கிளிகளைப் போல் தங்களின் மண்ணறைகளிலிருந்து (கப்ருகளிலிருந்து) வெளியேறுவார்கள்.) அழைப்பவருக்குப் பதிலளிக்கும் விதமாக, நாலாபுறமும் பரவிக்கிடக்கும் வெட்டுக்கிளிக் கூட்டங்களைப் போல, அவர்கள் விசாரணை நடைபெறும் இடத்தை நோக்கி மிகுந்த வேகத்துடனும் கூட்டமாகவும் திரள்வார்கள். அல்லாஹ் கூறினான்: ﴾مُهْطِعِينَ﴿\n\r\n\n\r\n(விரைந்து செல்பவர்களாக), அதாவது மிக விரைவாக, ﴾إِلَى الدَّاعِ﴿\n\r\n\n\r\n(அழைப்பவரை நோக்கி), அவர்களால் தயங்கவோ அல்லது வேகத்தைக் குறைக்கவோ முடியாது, ﴾يَقُولُ الْكَافِرُونَ هَذَا يَوْمٌ عَسِرٌ﴿\n\r\n\n\r\n(நிராகரிப்பாளர்கள் கூறுவார்கள்: \"இது ஒரு கடினமான நாள்.\") அதாவது, \"இது ஒரு கடினமான, பயங்கரமான, அச்சமூட்டும் மற்றும் வேதனைமிக்க நாள்.\" ﴾فَذَلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ - عَلَى الْكَافِرِينَ غَيْرُ يَسِيرٍ ﴿\n\r\n\n\r\n(நிச்சயமாக, அந்த நாள் ஒரு கடினமான நாளாகும்; அது நிராகரிப்பாளர்களுக்கு எளியதல்ல.) (74:9-10)"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=17\" class=\"link\">54:17</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:17 ஐ பார்க்கவும்"},"17":{"html":"<strong>நூஹ் (அலை) அவர்களின் சமூகத்தினரின் கதை மற்றும் அதிலிருந்து கிடைக்கும் படிப்பினை</strong><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">قَبْلَهُمْ﴿</span> (பொய்யாக்கினார்கள்) \"முஹம்மதே (ஸல்)! உமது மக்களுக்கு முன்பே,\" <span class=\"quran-arabic-font text-success\">﴾قَوْمُ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">فَكَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">عَبْدَنَا﴿</span> (நூஹ் உடைய சமூகத்தினர் (நம் தூதரைப்) பொய்யாக்கினார்கள்). அதாவது, அவர்கள் அவரைத் திட்டவட்டமாகப் பொய்யாக்கி, பைத்தியக்காரர் என்று குற்றம் சாட்டினார்கள். <span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَجْنُونٌ</span> <span class=\"quran-arabic-font text-success\">وَازْدُجِرَ﴿</span> (மேலும், \"அவர் ஒரு பைத்தியக்காரர்!\" என்று கூறி அவரை விரட்டினார்கள் (வஸ்துஜிர்).)<br />\r\n<br />\r\n'வஸ்துஜிர்' என்பதைப் பற்றி முஜாஹித் (ரஹ்) கூறினார்கள்: \"பைத்தியக்காரத்தனம் என்று குற்றம் சாட்டப்பட்டு அவர் விரட்டப்பட்டார்.\" 'வஸ்துஜிர்' என்பதற்கு, அவர் தனது சமூகத்தினரால் கண்டிக்கப்பட்டார், தடுக்கப்பட்டார், அச்சுறுத்தப்பட்டார் மற்றும் எச்சரிக்கப்பட்டார் என்றும் கூறப்படுகிறது: <span class=\"quran-arabic-font text-success\">﴾لَئِنْ</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَنْتَهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">نُوحُ</span> <span class=\"quran-arabic-font text-success\">لَتَكُونَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْجُومِينَ﴿</span> (\"நூஹே! நீர் (இதை விட்டும்) விலகிக் கொள்ளாவிட்டால், நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுபவர்களில் ஒருவராகிவிடுவீர்.\") <a href=\"qurandisp.php?sura=26&ayah=116\" class=\"link\">26:116</a>. இதனை இப்னு ஸைத் (ரழி) அவர்கள் கூறினார்கள்; இது சரியான கருத்தாகும். <span class=\"quran-arabic-font text-success\">﴾فَدَعَا</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنِّي</span> <span class=\"quran-arabic-font text-success\">مَغْلُوبٌ</span> <span class=\"quran-arabic-font text-success\">فَانتَصِرْ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (எனவே அவர் தனது இறைவனிடம், \"நிச்சயமாக நான் தோற்கடிக்கப்பட்டவன் ஆகிவிட்டேன்; ஆகவே (எனக்கு) உதவி செய்வாயாக!\" என்று பிரார்த்தித்தார்.)<br />\r\n<br />\r\nஅதாவது, 'நான் பலவீனமானவன், எனது மக்களை என்னால் வெல்லவோ எதிர்க்கவோ முடியாது, எனவே உனது மார்க்கத்திற்கு உதவி செய்வாயாக!' என்பதாகும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾فَفَتَحْنَآ</span> <span class=\"quran-arabic-font text-success\">أَبْوَابَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">بِمَاءٍ</span> <span class=\"quran-arabic-font text-success\">مُّنْهَمِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (ஆகவே, நாம் வானத்தின் வாசல்களைக் கொட்டும் நீரைக் கொண்டு (முன்ஹமிர்) திறந்து விட்டோம்.) 'முன்ஹமிர்' என்பது பற்றி அஸ்-ஸுத்தி கூறினார்கள், \"இதன் பொருள் 'ஏராளமான' என்பதாகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَفَجَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">عُيُوناً﴿</span> (மேலும், பூமியிலிருந்து நீரூற்றுகளைப் பொங்கிப் பாயச் செய்தோம்.) அதாவது, பூமியின் ஒவ்வொரு பகுதியிலிருந்தும், நெருப்பு எரிந்து கொண்டிருந்த அடுப்புகளில் இருந்து கூட நீரூற்றுகள் பீறிட்டு வந்தன. <span class=\"quran-arabic-font text-success\">﴾فَالْتَقَى</span> <span class=\"quran-arabic-font text-success\">المَآءُ﴿</span> (ஆகவே, அந்த இரு நீர்களும் சங்கமித்தன), அதாவது வானம் மற்றும் பூமியின் நீர், <span class=\"quran-arabic-font text-success\">﴾عَلَى</span> <span class=\"quran-arabic-font text-success\">أَمْرٍ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قُدِرَ﴿</span> (முன்னரே தீர்மானிக்கப்பட்ட ஒரு காரியத்திற்காக).<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இப்னு ஜுரைஜ் அறிவித்தார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَفَتَحْنَآ</span> <span class=\"quran-arabic-font text-success\">أَبْوَابَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">بِمَاءٍ</span> <span class=\"quran-arabic-font text-success\">مُّنْهَمِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (ஆகவே, நாம் வானத்தின் வாசல்களைக் கொட்டும் நீரைக் கொண்டு திறந்து விட்டோம்.) அன்றைய நாளுக்கு முன்பும் சரி, அதன் பின்பும் சரி, வானத்திலிருந்து பெய்த மழை நீர் மேகங்களில் இருந்துதான் பெய்தது. ஆனால், அன்று வானத்தின் வாசல்களே திறக்கப்பட்டன; எனவே அன்று இறங்கிய நீர் மேகங்களிலிருந்து வரவில்லை. இவ்வாறு (பூமி மற்றும் வானத்தின்) இரு நீர்களும் நிர்ணயிக்கப்பட்ட ஒரு காரியத்தின்படி சங்கமித்தன. அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾وَحَمَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">أَلْوَاحٍ</span> <span class=\"quran-arabic-font text-success\">وَدُسُرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும், பலகைகளாலும் ஆணிகளாலும் (துஸுர்) செய்யப்பட்ட ஒரு கப்பலில் நாம் அவரைச் சுமந்து சென்றோம்). இப்னு அப்பாஸ் (ரழி), ஸயீத் பின் ஜுபைர், அல்-குரழீ, கத்தாதா மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர் 'துஸுர்' என்பது ஆணிகளைக் குறிக்கும் என்று கூறினர். இப்னு ஜரீர் (ரஹ்) இந்த விளக்கத்தையே சிறந்ததாகக் கருதினார்.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று, <span class=\"quran-arabic-font text-success\">﴾تَجْرِى</span> <span class=\"quran-arabic-font text-success\">بِأَعْيُنِنَا﴿</span> (அது நமது கண்காணிப்பில் மிதந்து சென்றது), அதாவது 'நமது கட்டளைப்படியும், நமது பாதுகாப்பு மற்றும் கண்காணிப்பின் கீழும் (சென்றது)' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾جَزَآءً</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">كُفِرَ﴿</span> (நிராகரிக்கப்பட்டவருக்குக் கூலியாக!) அதாவது, அவர்கள் அல்லாஹ்வை நிராகரித்ததற்காக அவர்களுக்கு வழங்கப்பட்ட தண்டனையாகவும், நூஹ் (அலை) அவர்களுக்கு வழங்கப்பட்ட நற்கூலியாகவும் இது அமைந்தது.<br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">تَرَكْنَاهَا</span> <span class=\"quran-arabic-font text-success\">آيَةً﴿</span> (மேலும், நிச்சயமாக நாம் இதனை ஓர் அத்தாட்சியாக விட்டு வைத்துள்ளோம்.) கத்தாதா கூறினார்கள், \"இந்த உம்மத்தின் முதல் தலைமுறையினர் பார்க்கும் வரை அல்லாஹ் நூஹ் (அலை) அவர்களின் கப்பலை அழியாமல் விட்டு வைத்திருந்தான்.\" இருப்பினும், இதன் நேரடிப் பொருள் யாதெனில், அல்லாஹ் கப்பல்களை ஓர் அத்தாட்சியாக வைத்திருக்கிறான் என்பதாகும். உதாரணமாக, உயர்ந்தோனாகிய அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَآيَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّا</span> <span class=\"quran-arabic-font text-success\">حَمَلْنَا</span> <span class=\"quran-arabic-font text-success\">ذُرِّيَّتَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">الْمَشْحُونِ</span> - <span class=\"quran-arabic-font text-success\">وَخَلَقْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مِّثْلِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَرْكَبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (மேலும் அவர்களுக்கோர் அத்தாட்சியாவது: நிச்சயமாக நாம் அவர்களுடைய சந்ததிகளை (நிரப்பப்பட்ட) பாரமான கப்பலில் சுமந்து சென்றோம். இன்னும் அவர்கள் ஏறிச் செல்லக்கூடிய இது போன்றவற்றை அவர்களுக்காக நாம் படைத்தோம்.) (<a href=\"qurandisp.php?sura=36&ayah=41\" class=\"link\">36:41</a>-42). <span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">طَغَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءُ</span> <span class=\"quran-arabic-font text-success\">حَمَلْنَاكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْجَارِيَةِ</span> - <span class=\"quran-arabic-font text-success\">لِنَجْعَلَهَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةً</span> <span class=\"quran-arabic-font text-success\">وَتَعِيَهَا</span> <span class=\"quran-arabic-font text-success\">أُذُنٌ</span> <span class=\"quran-arabic-font text-success\">وَاعِيَةٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாகத் தண்ணீர் பெருக்கெடுத்த போது, நாம் உங்களை ஒரு கப்பலில் சுமந்து சென்றோம். அதனை உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காகவும், நினைவு வைத்துக் கொள்ளும் காதுகள் அதனைத் தக்க வைத்துக் கொள்வதற்காகவும் (இவ்வாறு செய்தோம்).) (<a href=\"qurandisp.php?sura=69&ayah=11\" class=\"link\">69:11</a>-12).<br />\r\n<br />\r\nஇங்கு அல்லாஹ்வின் கூற்று, <span class=\"quran-arabic-font text-success\">﴾فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ﴿</span> (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?) அதாவது, 'இதன் மூலம் நல்லுபதேசத்தையும் நினைவூட்டலையும் பெறுபவர் எவரேனும் உண்டா?' என்பதாகும். இமாம் அஹ்மத் (ரஹ்) அவர்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"நபி (ஸல்) அவர்கள் எனக்கு <span class=\"quran-arabic-font text-success\">﴾فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ﴿</span> என்று ஓதிக் காட்டினார்கள்.\" இமாம் புகாரி (ரஹ்) அவர்களும் அப்துல்லாஹ் (ரழி) அவர்களிடமிருந்து இதே போன்ற ஒரு ஹதீஸைப் பதிவு செய்துள்ளார்கள்: \"நான் நபி (ஸல்) அவர்களிடம் (<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّذَّكِرٍ</span>) என்று ஓதினேன். அதற்கு நபி (ஸல்) அவர்கள் <span class=\"quran-arabic-font text-success\">﴾فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ﴿</span> (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?) என்று ஓதிக் காட்டினார்கள்.\"<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று, <span class=\"quran-arabic-font text-success\">﴾فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابِى</span> <span class=\"quran-arabic-font text-success\">وَنُذُرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அப்படியாயின், எனது வேதனையும் எனது எச்சரிக்கைகளும் எவ்வாறு இருந்தன?) அதாவது, 'என்னை நிராகரித்து, எனது தூதர்களைப் பொய்யாக்கி, எனது எச்சரிக்கைகளுக்குச் செவிசாய்க்காதவர்களுக்கு நான் வழங்கிய தண்டனை எவ்வளவு கடுமையானதாக இருந்தது! எனது தூதர்களுக்கு நான் புரிந்த உதவியும், அவர்கள் சார்பாக நான் எடுத்த பழிவாங்கலும் எவ்வாறு இருந்தது?' என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِلذِّكْرِ﴿</span> (நிச்சயமாக நாம் இந்த குர்ஆனை நினைவூட்டலுக்காக எளிதாக்கியுள்ளோம்); அதாவது, 'மனிதர்களுக்கு நினைவூட்டுவதற்காகவும், அதன்பால் ஈர்க்கப்படுபவர்களுக்கு குர்ஆனை ஓதுவதையும் புரிந்து கொள்வதையும் நாம் எளிதாக்கியுள்ளோம்.' அல்லாஹ் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾كِتَابٌ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مُبَارَكٌ</span> <span class=\"quran-arabic-font text-success\">لِّيَدَّبَّرُواْ</span> <span class=\"quran-arabic-font text-success\">آيَاتِهِ</span> <span class=\"quran-arabic-font text-success\">وَلِيَتَذَكَّرَ</span> <span class=\"quran-arabic-font text-success\">أُوْلُو</span> <span class=\"quran-arabic-font text-success\">الْأَلْبَابِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> ((இது) பாக்கியம் பெற்ற ஒரு வேதம்; நாம் இதனை உமக்கு அருளியுள்ளோம் - அவர்கள் இதன் வசனங்களை ஆழ்ந்து சிந்திப்பதற்காகவும், அறிவுடையோர் நல்லுபதேசம் பெறுவதற்காகவும்.) (<a href=\"qurandisp.php?sura=38&ayah=29\" class=\"link\">38:29</a>). <span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِلَسَانِكَ</span> <span class=\"quran-arabic-font text-success\">لِتُبَشِّرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">وَتُنْذِرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">لُّدّاً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக நாம் இதனை (குர்ஆனை) உமது மொழியில் எளிதாக்கியதெல்லாம், இதைக் கொண்டு நீர் இறையச்சமுடையவர்களுக்கு நன்மாராயங் கூறவும், வீண் பிடிவாதம் செய்யும் மக்களுக்கு எச்சரிக்கை செய்யவுமே ஆகும்.) (<a href=\"qurandisp.php?sura=19&ayah=97\" class=\"link\">19:97</a>).<br />\r\n<br />\r\nஅல்லாஹ் கூறினான், <span class=\"quran-arabic-font text-success\">﴾فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ﴿</span> (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?), அதாவது 'மனப்பாடம் செய்வதற்கும் புரிந்து கொள்வதற்கும் நாம் எளிதாக்கிய இந்த குர்ஆனின் மூலம் நல்லுபதேசம் பெறுபவர் எவருமுண்டா?' முஹம்மது பின் கஅப் அல்-குரழீ இந்த வசனத்திற்கு விளக்கமளிக்கையில், \"தீமையைத் தவிர்ப்பவர் எவரேனும் உண்டா?\" என்று கூறினார். மதர் அல்-வர்ராக் (ரஹ்) அவர்கள், \"அல்லாஹ்வை நினைவுகூர்ந்து, (அதன் மூலம்) அவனது உதவியைப் பெறுபவர் உண்டா?\" என்று கூறினார்கள்.<br />\r\n<br />","text":"நூஹ் (அலை) அவர்களின் சமூகத்தினரின் கதை மற்றும் அதிலிருந்து கிடைக்கும் படிப்பினை\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், ﴾كَذَّبَتْ قَبْلَهُمْ﴿ (பொய்யாக்கினார்கள்) \"முஹம்மதே (ஸல்)! உமது மக்களுக்கு முன்பே,\" ﴾قَوْمُ نُوحٍ فَكَذَّبُواْ عَبْدَنَا﴿ (நூஹ் உடைய சமூகத்தினர் (நம் தூதரைப்) பொய்யாக்கினார்கள்). அதாவது, அவர்கள் அவரைத் திட்டவட்டமாகப் பொய்யாக்கி, பைத்தியக்காரர் என்று குற்றம் சாட்டினார்கள். ﴾وَقَالُواْ مَجْنُونٌ وَازْدُجِرَ﴿ (மேலும், \"அவர் ஒரு பைத்தியக்காரர்!\" என்று கூறி அவரை விரட்டினார்கள் (வஸ்துஜிர்).)\n\r\n\n\r\n'வஸ்துஜிர்' என்பதைப் பற்றி முஜாஹித் (ரஹ்) கூறினார்கள்: \"பைத்தியக்காரத்தனம் என்று குற்றம் சாட்டப்பட்டு அவர் விரட்டப்பட்டார்.\" 'வஸ்துஜிர்' என்பதற்கு, அவர் தனது சமூகத்தினரால் கண்டிக்கப்பட்டார், தடுக்கப்பட்டார், அச்சுறுத்தப்பட்டார் மற்றும் எச்சரிக்கப்பட்டார் என்றும் கூறப்படுகிறது: ﴾لَئِنْ لَّمْ تَنْتَهِ يَا نُوحُ لَتَكُونَنَّ مِنَ الْمُرْجُومِينَ﴿ (\"நூஹே! நீர் (இதை விட்டும்) விலகிக் கொள்ளாவிட்டால், நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுபவர்களில் ஒருவராகிவிடுவீர்.\") 26:116. இதனை இப்னு ஸைத் (ரழி) அவர்கள் கூறினார்கள்; இது சரியான கருத்தாகும். ﴾فَدَعَا رَبَّهُ أَنِّي مَغْلُوبٌ فَانتَصِرْ ﴿ (எனவே அவர் தனது இறைவனிடம், \"நிச்சயமாக நான் தோற்கடிக்கப்பட்டவன் ஆகிவிட்டேன்; ஆகவே (எனக்கு) உதவி செய்வாயாக!\" என்று பிரார்த்தித்தார்.)\n\r\n\n\r\nஅதாவது, 'நான் பலவீனமானவன், எனது மக்களை என்னால் வெல்லவோ எதிர்க்கவோ முடியாது, எனவே உனது மார்க்கத்திற்கு உதவி செய்வாயாக!' என்பதாகும். உயர்ந்தோனாகிய அல்லாஹ் கூறினான், ﴾فَفَتَحْنَآ أَبْوَابَ السَّمَآءِ بِمَاءٍ مُّنْهَمِرٍ ﴿ (ஆகவே, நாம் வானத்தின் வாசல்களைக் கொட்டும் நீரைக் கொண்டு (முன்ஹமிர்) திறந்து விட்டோம்.) 'முன்ஹமிர்' என்பது பற்றி அஸ்-ஸுத்தி கூறினார்கள், \"இதன் பொருள் 'ஏராளமான' என்பதாகும்.\"\n\r\n\n\r\n﴾وَفَجَّرْنَا الْأَرْضَ عُيُوناً﴿ (மேலும், பூமியிலிருந்து நீரூற்றுகளைப் பொங்கிப் பாயச் செய்தோம்.) அதாவது, பூமியின் ஒவ்வொரு பகுதியிலிருந்தும், நெருப்பு எரிந்து கொண்டிருந்த அடுப்புகளில் இருந்து கூட நீரூற்றுகள் பீறிட்டு வந்தன. ﴾فَالْتَقَى المَآءُ﴿ (ஆகவே, அந்த இரு நீர்களும் சங்கமித்தன), அதாவது வானம் மற்றும் பூமியின் நீர், ﴾عَلَى أَمْرٍ قَدْ قُدِرَ﴿ (முன்னரே தீர்மானிக்கப்பட்ட ஒரு காரியத்திற்காக).\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து இப்னு ஜுரைஜ் அறிவித்தார்கள்: ﴾فَفَتَحْنَآ أَبْوَابَ السَّمَآءِ بِمَاءٍ مُّنْهَمِرٍ ﴿ (ஆகவே, நாம் வானத்தின் வாசல்களைக் கொட்டும் நீரைக் கொண்டு திறந்து விட்டோம்.) அன்றைய நாளுக்கு முன்பும் சரி, அதன் பின்பும் சரி, வானத்திலிருந்து பெய்த மழை நீர் மேகங்களில் இருந்துதான் பெய்தது. ஆனால், அன்று வானத்தின் வாசல்களே திறக்கப்பட்டன; எனவே அன்று இறங்கிய நீர் மேகங்களிலிருந்து வரவில்லை. இவ்வாறு (பூமி மற்றும் வானத்தின்) இரு நீர்களும் நிர்ணயிக்கப்பட்ட ஒரு காரியத்தின்படி சங்கமித்தன. அல்லாஹ் கூறினான், ﴾وَحَمَلْنَاهُ عَلَى ذَاتِ أَلْوَاحٍ وَدُسُرٍ ﴿ (மேலும், பலகைகளாலும் ஆணிகளாலும் (துஸுர்) செய்யப்பட்ட ஒரு கப்பலில் நாம் அவரைச் சுமந்து சென்றோம்). இப்னு அப்பாஸ் (ரழி), ஸயீத் பின் ஜுபைர், அல்-குரழீ, கத்தாதா மற்றும் இப்னு ஸைத் (ரழி) ஆகியோர் 'துஸுர்' என்பது ஆணிகளைக் குறிக்கும் என்று கூறினர். இப்னு ஜரீர் (ரஹ்) இந்த விளக்கத்தையே சிறந்ததாகக் கருதினார்.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று, ﴾تَجْرِى بِأَعْيُنِنَا﴿ (அது நமது கண்காணிப்பில் மிதந்து சென்றது), அதாவது 'நமது கட்டளைப்படியும், நமது பாதுகாப்பு மற்றும் கண்காணிப்பின் கீழும் (சென்றது)' என்பதாகும். ﴾جَزَآءً لِّمَن كَانَ كُفِرَ﴿ (நிராகரிக்கப்பட்டவருக்குக் கூலியாக!) அதாவது, அவர்கள் அல்லாஹ்வை நிராகரித்ததற்காக அவர்களுக்கு வழங்கப்பட்ட தண்டனையாகவும், நூஹ் (அலை) அவர்களுக்கு வழங்கப்பட்ட நற்கூலியாகவும் இது அமைந்தது.\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ் கூறினான், ﴾وَلَقَدْ تَرَكْنَاهَا آيَةً﴿ (மேலும், நிச்சயமாக நாம் இதனை ஓர் அத்தாட்சியாக விட்டு வைத்துள்ளோம்.) கத்தாதா கூறினார்கள், \"இந்த உம்மத்தின் முதல் தலைமுறையினர் பார்க்கும் வரை அல்லாஹ் நூஹ் (அலை) அவர்களின் கப்பலை அழியாமல் விட்டு வைத்திருந்தான்.\" இருப்பினும், இதன் நேரடிப் பொருள் யாதெனில், அல்லாஹ் கப்பல்களை ஓர் அத்தாட்சியாக வைத்திருக்கிறான் என்பதாகும். உதாரணமாக, உயர்ந்தோனாகிய அல்லாஹ் கூறினான்: ﴾وَآيَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى الْفُلْكِ الْمَشْحُونِ - وَخَلَقْنَا لَهُمْ مِّن مِّثْلِهِ مَا يَرْكَبُونَ ﴿ (மேலும் அவர்களுக்கோர் அத்தாட்சியாவது: நிச்சயமாக நாம் அவர்களுடைய சந்ததிகளை (நிரப்பப்பட்ட) பாரமான கப்பலில் சுமந்து சென்றோம். இன்னும் அவர்கள் ஏறிச் செல்லக்கூடிய இது போன்றவற்றை அவர்களுக்காக நாம் படைத்தோம்.) (36:41-42). ﴾إِنَّا لَمَّا طَغَا الْمَآءُ حَمَلْنَاكُمْ فِى الْجَارِيَةِ - لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَا أُذُنٌ وَاعِيَةٌ ﴿ (நிச்சயமாகத் தண்ணீர் பெருக்கெடுத்த போது, நாம் உங்களை ஒரு கப்பலில் சுமந்து சென்றோம். அதனை உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காகவும், நினைவு வைத்துக் கொள்ளும் காதுகள் அதனைத் தக்க வைத்துக் கொள்வதற்காகவும் (இவ்வாறு செய்தோம்).) (69:11-12).\n\r\n\n\r\nஇங்கு அல்லாஹ்வின் கூற்று, ﴾فَهَلْ مِن مُّدَّكِرٍ﴿ (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?) அதாவது, 'இதன் மூலம் நல்லுபதேசத்தையும் நினைவூட்டலையும் பெறுபவர் எவரேனும் உண்டா?' என்பதாகும். இமாம் அஹ்மத் (ரஹ்) அவர்கள், அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"நபி (ஸல்) அவர்கள் எனக்கு ﴾فَهَلْ مِن مُّدَّكِرٍ﴿ என்று ஓதிக் காட்டினார்கள்.\" இமாம் புகாரி (ரஹ்) அவர்களும் அப்துல்லாஹ் (ரழி) அவர்களிடமிருந்து இதே போன்ற ஒரு ஹதீஸைப் பதிவு செய்துள்ளார்கள்: \"நான் நபி (ஸல்) அவர்களிடம் (فَهَلْ مِن مُّذَّكِرٍ) என்று ஓதினேன். அதற்கு நபி (ஸல்) அவர்கள் ﴾فَهَلْ مِن مُّدَّكِرٍ﴿ (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?) என்று ஓதிக் காட்டினார்கள்.\"\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று, ﴾فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ ﴿ (அப்படியாயின், எனது வேதனையும் எனது எச்சரிக்கைகளும் எவ்வாறு இருந்தன?) அதாவது, 'என்னை நிராகரித்து, எனது தூதர்களைப் பொய்யாக்கி, எனது எச்சரிக்கைகளுக்குச் செவிசாய்க்காதவர்களுக்கு நான் வழங்கிய தண்டனை எவ்வளவு கடுமையானதாக இருந்தது! எனது தூதர்களுக்கு நான் புரிந்த உதவியும், அவர்கள் சார்பாக நான் எடுத்த பழிவாங்கலும் எவ்வாறு இருந்தது?' என்பதாகும்.\n\r\n\n\r\n﴾وَلَقَدْ يَسَّرْنَا الْقُرْءَانَ لِلذِّكْرِ﴿ (நிச்சயமாக நாம் இந்த குர்ஆனை நினைவூட்டலுக்காக எளிதாக்கியுள்ளோம்); அதாவது, 'மனிதர்களுக்கு நினைவூட்டுவதற்காகவும், அதன்பால் ஈர்க்கப்படுபவர்களுக்கு குர்ஆனை ஓதுவதையும் புரிந்து கொள்வதையும் நாம் எளிதாக்கியுள்ளோம்.' அல்லாஹ் கூறுவது போல: ﴾كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِّيَدَّبَّرُواْ آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُو الْأَلْبَابِ ﴿ ((இது) பாக்கியம் பெற்ற ஒரு வேதம்; நாம் இதனை உமக்கு அருளியுள்ளோம் - அவர்கள் இதன் வசனங்களை ஆழ்ந்து சிந்திப்பதற்காகவும், அறிவுடையோர் நல்லுபதேசம் பெறுவதற்காகவும்.) (38:29). ﴾فَإِنَّمَا يَسَّرْنَاهُ بِلَسَانِكَ لِتُبَشِّرَ بِهِ الْمُتَّقِينَ وَتُنْذِرَ بِهِ قَوْماً لُّدّاً ﴿ (நிச்சயமாக நாம் இதனை (குர்ஆனை) உமது மொழியில் எளிதாக்கியதெல்லாம், இதைக் கொண்டு நீர் இறையச்சமுடையவர்களுக்கு நன்மாராயங் கூறவும், வீண் பிடிவாதம் செய்யும் மக்களுக்கு எச்சரிக்கை செய்யவுமே ஆகும்.) (19:97).\n\r\n\n\r\nஅல்லாஹ் கூறினான், ﴾فَهَلْ مِن مُّدَّكِرٍ﴿ (எனவே, படிப்பினை பெறுவோர் எவருமுண்டா?), அதாவது 'மனப்பாடம் செய்வதற்கும் புரிந்து கொள்வதற்கும் நாம் எளிதாக்கிய இந்த குர்ஆனின் மூலம் நல்லுபதேசம் பெறுபவர் எவருமுண்டா?' முஹம்மது பின் கஅப் அல்-குரழீ இந்த வசனத்திற்கு விளக்கமளிக்கையில், \"தீமையைத் தவிர்ப்பவர் எவரேனும் உண்டா?\" என்று கூறினார். மதர் அல்-வர்ராக் (ரஹ்) அவர்கள், \"அல்லாஹ்வை நினைவுகூர்ந்து, (அதன் மூலம்) அவனது உதவியைப் பெறுபவர் உண்டா?\" என்று கூறினார்கள்."},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=22\" class=\"link\">54:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:22 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=22\" class=\"link\">54:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:22 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=22\" class=\"link\">54:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:22 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=22\" class=\"link\">54:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:22 ஐ பார்க்கவும்"},"22":{"html":"<strong>ஆத் சமூகத்தின் வரலாறு: நூஹ் (அலை) அவர்களின் சமூகத்தினர் (தங்கள் தூதரைப்) பொய்யாக்கியதைப் போலவே, ஹூத் (அலை) அவர்களின் சமூகமான ஆத் கூட்டத்தினரும் தங்கள் தூதரைப் பொய்யாக்கினார்கள் என்று அல்லாஹ் கூறுகிறான்.</strong><br />\r\n<br />\r\nஎனவே, அல்லாஹ் அவர்கள் மீது <span class=\"quran-arabic-font text-success\">﴾عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">رِيحاً</span> <span class=\"quran-arabic-font text-success\">صَرْصَراً﴿</span> (கடும் குளிரான – ஸர்ஸர் – காற்றை) அனுப்பினான். இதற்கு மிகக் கடுமையான குளிர்ச்சியும் சீற்றமும் கொண்ட காற்று என்று பொருள்.<br />\r\n<br />\r\nஅவர்களுக்கு எதிரான <span class=\"quran-arabic-font text-success\">﴾فِي</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">نَحْسٍ﴿</span> (ஒரு துரதிர்ஷ்டவசமான நாளில்) அதாவது புதன்கிழமை என்று ளஹ்ஹாக், கதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகின்றனர்.<br />\r\n<br />\r\nஅது அவர்கள் மீது <span class=\"quran-arabic-font text-success\">﴾مُسْتَمِرٍّ﴿</span> (தொடர்ச்சியாக இருந்தது). ஏனெனில் அந்த நாளில் இவ்வுலகில் அவர்கள் அனுபவித்த துயரம், வேதனை மற்றும் அழிவு ஆகியவை மறுமையின் வேதனையோடும் இணைந்ததாகத் தொடர்ந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَنزِعُ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَازُ</span> <span class=\"quran-arabic-font text-success\">نَخْلٍ</span> <span class=\"quran-arabic-font text-success\">مُّنقَعِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (வேரோடு பிடுங்கப்பட்ட பேரீச்சை மரங்களின் அடிமரங்களைப் போல் மனிதர்களை அது பிடுங்கி எறிந்தது). அக்காற்று மனிதர்களில் ஒருவரைப் பிடுங்கி, அவர் கண்ணுக்குத் தெரியாத உயரத்திற்குத் தூக்கிச் சென்று, பின்னர் அவரைத் தலைகீழாகத் தரையில் பலமாக வீசியெறியும். அவரது தலை சிதறிப் போய், தலையில்லாத முண்டமாக மட்டுமே அவர் எஞ்சியிருப்பார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَازُ</span> <span class=\"quran-arabic-font text-success\">نَخْلٍ</span> <span class=\"quran-arabic-font text-success\">مُّنقَعِرٍ</span> <span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابِي</span> <span class=\"quran-arabic-font text-success\">وَنُذُرِ</span> <span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانَ</span> <span class=\"quran-arabic-font text-success\">لِلذِّكْرِ</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அவர்கள் வேரோடு சாய்ந்த பேரீச்சை மரங்களின் அடிமரங்களைப் போல் இருந்தனர். எனவே, எனது வேதனையும் எனது எச்சரிக்கைகளும் எவ்வாறு இருந்தன? மேலும், நிச்சயமாக நாம் இந்தக் குர்ஆனைப் படித்து நினைவுபடுத்திக் கொள்வதற்கு மிக எளிதாக்கினோம்; எனவே படிப்பினை பெறுவோர் எவரேனும் உண்டா?)<br />\r\n<br />","text":"ஆத் சமூகத்தின் வரலாறு: நூஹ் (அலை) அவர்களின் சமூகத்தினர் (தங்கள் தூதரைப்) பொய்யாக்கியதைப் போலவே, ஹூத் (அலை) அவர்களின் சமூகமான ஆத் கூட்டத்தினரும் தங்கள் தூதரைப் பொய்யாக்கினார்கள் என்று அல்லாஹ் கூறுகிறான்.\n\r\n\n\r\nஎனவே, அல்லாஹ் அவர்கள் மீது ﴾عَلَيْهِمْ رِيحاً صَرْصَراً﴿ (கடும் குளிரான – ஸர்ஸர் – காற்றை) அனுப்பினான். இதற்கு மிகக் கடுமையான குளிர்ச்சியும் சீற்றமும் கொண்ட காற்று என்று பொருள்.\n\r\n\n\r\nஅவர்களுக்கு எதிரான ﴾فِي يَوْمِ نَحْسٍ﴿ (ஒரு துரதிர்ஷ்டவசமான நாளில்) அதாவது புதன்கிழமை என்று ளஹ்ஹாக், கதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகின்றனர்.\n\r\n\n\r\nஅது அவர்கள் மீது ﴾مُسْتَمِرٍّ﴿ (தொடர்ச்சியாக இருந்தது). ஏனெனில் அந்த நாளில் இவ்வுலகில் அவர்கள் அனுபவித்த துயரம், வேதனை மற்றும் அழிவு ஆகியவை மறுமையின் வேதனையோடும் இணைந்ததாகத் தொடர்ந்தது.\n\r\n\n\r\n﴾تَنزِعُ النَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ ﴿ (வேரோடு பிடுங்கப்பட்ட பேரீச்சை மரங்களின் அடிமரங்களைப் போல் மனிதர்களை அது பிடுங்கி எறிந்தது). அக்காற்று மனிதர்களில் ஒருவரைப் பிடுங்கி, அவர் கண்ணுக்குத் தெரியாத உயரத்திற்குத் தூக்கிச் சென்று, பின்னர் அவரைத் தலைகீழாகத் தரையில் பலமாக வீசியெறியும். அவரது தலை சிதறிப் போய், தலையில்லாத முண்டமாக மட்டுமே அவர் எஞ்சியிருப்பார்.\n\r\n\n\r\n﴾كَأَنَّهُمْ أَعْجَازُ نَخْلٍ مُّنقَعِرٍ فَكَيْفَ كَانَ عَذَابِي وَنُذُرِ وَلَقَدْ يَسَّرْنَا الْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ ﴿ (அவர்கள் வேரோடு சாய்ந்த பேரீச்சை மரங்களின் அடிமரங்களைப் போல் இருந்தனர். எனவே, எனது வேதனையும் எனது எச்சரிக்கைகளும் எவ்வாறு இருந்தன? மேலும், நிச்சயமாக நாம் இந்தக் குர்ஆனைப் படித்து நினைவுபடுத்திக் கொள்வதற்கு மிக எளிதாக்கினோம்; எனவே படிப்பினை பெறுவோர் எவரேனும் உண்டா?)"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=32\" class=\"link\">54:32</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:32 ஐ பார்க்கவும்"},"32":{"html":"<strong>ஸமூது கூட்டத்தினரின் வரலாறு</strong><br />\r\n<br />\r\nஸமூது சமூகத்தினர் தங்களுடைய தூதர் ஸாலிஹ் (அலை) அவர்களைப் பொய்ப்பித்ததாக அல்லாஹ் இங்கு கூறுகிறான், <span class=\"quran-arabic-font text-success\">﴾كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">ثَمُودُ</span> <span class=\"quran-arabic-font text-success\">بِالنُّذُرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">﴾فَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَبَشَرًا</span> <span class=\"quran-arabic-font text-success\">مِّنَّا</span> <span class=\"quran-arabic-font text-success\">وَاحِدًا</span> <span class=\"quran-arabic-font text-success\">نَّتَّبِعُهُ</span> <span class=\"quran-arabic-font text-success\">إِنَّآ</span> <span class=\"quran-arabic-font text-success\">إِذاً</span> <span class=\"quran-arabic-font text-success\">لَّفِى</span> <span class=\"quran-arabic-font text-success\">ضَلَـلٍ</span> <span class=\"quran-arabic-font text-success\">وَسُعُرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள், \"நம்மில் ஒரு மனிதரையா நாம் பின்பற்றுவோம்? அவ்வாறாயின், நிச்சயமாக நாம் வழிகேட்டிலும், வேதனையிலும் இருப்போம்!\" என்று கூறினார்கள்.) 'நம்மில் ஒரு மனிதருக்கு நாம் அனைவரும் கட்டுப்பட்டால், நாம் தோல்வியையும் நஷ்டத்தையுமே அடைவோம்' என்று அவர்கள் கூறினார்கள். தங்களில் ஒருவருக்கு மட்டும் இந்த அறிவுரை (வஹீ) வழங்கப்பட்டதைக் கண்டு அவர்கள் ஆச்சரியமடைந்தனர்; அதனால் அவரைப் பொய்யர் என்று குற்றம் சுமத்தினர், <span class=\"quran-arabic-font text-success\">﴾أَءُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِنَا</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">كَذَّابٌ</span> <span class=\"quran-arabic-font text-success\">أَشِرٌ﴿</span><br />\r\n<br />\r\n(இல்லை, அவர் ஒரு திமிர் பிடித்த பொய்யர்!), அதாவது, அவர் தனது பொய்களில் வரம்பு மீறிவிட்டார் என்று அவர்கள் கருதினர். அதற்கு மிக உயர்ந்தவனான அல்லாஹ், <span class=\"quran-arabic-font text-success\">﴾سَيَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">غَداً</span> <span class=\"quran-arabic-font text-success\">مَّنِ</span> <span class=\"quran-arabic-font text-success\">الْكَذَّابُ</span> <span class=\"quran-arabic-font text-success\">الْأَشِرُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(யார் அந்தத் திமிர் பிடித்த பொய்யர் என்பதை அவர்கள் நாளை அறிந்துகொள்வார்கள்!) என்று பதிலளித்தான். இதன் மூலம் அல்லாஹ் அவர்களை எச்சரித்து, அச்சுறுத்தி, ஒரு உறுதியான வாக்குறுதியையும் அளித்தான், <span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">مُرْسِلُواْ</span> <span class=\"quran-arabic-font text-success\">النَّاقَةِ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவர்களுக்குச் சோதனையாக ஒரு பெண் ஒட்டகத்தை அனுப்பப்போகிறோம்.) ஸமூது கூட்டத்தினரைச் சோதிப்பதற்காக, அவர்களின் கோரிக்கையின்படியே ஒரு திடமான பாறையிலிருந்து வெளிப்பட்ட ஒரு பிரம்மாண்டமான, சினை கொண்ட பெண் ஒட்டகத்தை அல்லாஹ் அவர்களுக்கு அனுப்பினான். அதன் பிறகு, அல்லாஹ்விடமிருந்து தங்களுக்கு வந்த ஒரு சான்றாக அதனை ஏற்று, ஸாலிஹ் (அலை) அவர்கள் கொண்டு வந்த செய்தியை அவர்கள் நம்ப வேண்டும் என்பதற்காகவே அவ்வாறு செய்தான். அல்லாஹ் தனது அடியாரும் தூதருமான ஸாலிஹ் (அலை) அவர்களுக்குக் கட்டளையிட்டான், <span class=\"quran-arabic-font text-success\">﴾فَارْتَقِبْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَاصْطَبِرْ﴿</span><br />\r\n<br />\r\n(எனவே அவர்களைக் கவனித்துக்கொண்டிருப்பீராக, மேலும் பொறுமையைக் கடைப்பிடிப்பீராக!) அல்லாஹ் கட்டளையிட்டான், 'ஸாலிஹே! காத்திருப்பீராக, அவர்களுக்கு என்ன நேரிடும் என்று கவனிப்பீராக, மேலும் பொறுமையாக இருப்பீராக; நிச்சயமாகச் சிறந்த முடிவு உமக்கே உரியதாகும், மேலும் நீர் இம்மையிலும் மறுமையிலும் வெற்றி பெறுவீர்.' <span class=\"quran-arabic-font text-success\">﴾وَنَبِّئْهُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَآءَ</span> <span class=\"quran-arabic-font text-success\">قِسْمَةٌ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ﴿</span><br />\r\n<br />\r\n(மேலும் தண்ணீர் அவர்களுக்கிடையே பங்கிடப்பட வேண்டும் என்று அவர்களுக்குத் தெரிவிப்பீராக.) ஒரு நாள் அந்த ஒட்டகம் குடிப்பதற்கும், மற்றொரு நாள் மக்கள் குடிப்பதற்கும் என்று ஒதுக்கப்பட்டது, <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">نَاقَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّهَا</span> <span class=\"quran-arabic-font text-success\">شِرْبٌ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">شِرْبُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">مَّعْلُومٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர் கூறினார்கள்: \"இதோ ஒரு பெண் ஒட்டகம்: அதற்கு ஒரு குறிப்பிட்ட நாளில் குடிப்பதற்கு உரிமை உண்டு, உங்களுக்கும் ஒரு குறிப்பிட்ட நாளில் குடிப்பதற்கு உரிமை உண்டு.\") (<a href=\"qurandisp.php?sura=26&ayah=155\" class=\"link\">26:155</a>) அல்லாஹ்வின் கூற்று, <span class=\"quran-arabic-font text-success\">﴾كُلُّ</span> <span class=\"quran-arabic-font text-success\">شِرْبٍ</span> <span class=\"quran-arabic-font text-success\">مُّحْتَضَرٌ﴿</span><br />\r\n<br />\r\n(ஒவ்வொருவரும் தங்களுக்குரிய முறைப்படி நீர் அருந்துவதற்கு ஆஜராக வேண்டும்.) முஜாஹித் (ரஹ்) கூறினார்கள்: \"அந்த ஒட்டகம் தண்ணீர் குடிக்காத நாட்களில் அவர்கள் தண்ணீரைப் பருகிக்கொள்வார்கள்; அது தண்ணீர் குடிக்கும் நாளில் அவர்கள் அதன் பாலைக் குடிப்பார்கள்.\" உயர்ந்தவனான அல்லாஹ் கூறினான்; <span class=\"quran-arabic-font text-success\">﴾فَنَادَوْاْ</span> <span class=\"quran-arabic-font text-success\">صَـحِبَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَتَعَاطَى</span> <span class=\"quran-arabic-font text-success\">فَعَقَرَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் தங்கள் தோழனை அழைத்தார்கள்; அவன் (அதைப்) பிடித்து, அதன் கால்களை வெட்டிக் கொன்றான்.) தஃப்ஸீர் அறிஞர்களின் கூற்றுப்படி, அவனது பெயர் குதார் பின் ஸாலிஃப் ஆகும்; அவன் அந்த மக்களிடையே மிகவும் கொடியவனாக இருந்தான், <span class=\"quran-arabic-font text-success\">﴾إِذِ</span> <span class=\"quran-arabic-font text-success\">انبَعَثَ</span> <span class=\"quran-arabic-font text-success\">أَشْقَـهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்களில் மிகவும் துர்ப்பாக்கியசாலி (அப்பெண் ஒட்டகத்தைக் கொல்ல) முன்வந்தபோது.) (<a href=\"qurandisp.php?sura=91&ayah=12\" class=\"link\">91:12</a>) அல்லாஹ் இங்கே கூறினான், <span class=\"quran-arabic-font text-success\">﴾فَتَعَاطَى﴿</span><br />\r\n<br />\r\n(மேலும் அவன் பிடித்தான்) அதாவது தீங்கு செய்யத் துணிந்தான், <span class=\"quran-arabic-font text-success\">﴾فَعَقَرَ</span> <span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابِى</span> <span class=\"quran-arabic-font text-success\">وَنُذُرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் (அவளை)க் கொன்றான். பிறகு, எனது வேதனையும் எனது எச்சரிக்கைகளும் எப்படி இருந்தன?) 'நான் அவர்களை வேதனை செய்தேன்; என்னை நிராகரித்ததாலும், எனது தூதரைப் பொய்ப்பித்ததாலும் நான் அவர்கள் மீது அனுப்பிய வேதனை எவ்வளவு கடுமையானதாக இருந்தது!' <span class=\"quran-arabic-font text-success\">﴾إِنَّآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">صَيْحَةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span> <span class=\"quran-arabic-font text-success\">فَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">كَهَشِيمِ</span> <span class=\"quran-arabic-font text-success\">الْمُحْتَظِرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அவர்கள் மீது ஒரேயொரு பேரொலியை (ஸய்ஹாவை) அனுப்பினோம்; அதனால் அவர்கள் வேலி அமைப்பவர் பயன்படுத்தும் காய்ந்த சருகுகளைப் போல் ஆகிவிட்டார்கள்.) அவர்கள் அனைவரும் அழிந்து போயினர்; அவர்களில் ஒருவரும் எஞ்சவில்லை. செடிகளும் புற்களும் காய்ந்து அழிந்து போவதைப் போல, அவர்களும் முற்றிலும் அழிந்து போயினர். அஸ்-ஸுத்தி (ரஹ்) கூறினார்கள்: \"அவர்கள் பாலைவனத்தில் காய்ந்து எரிக்கப்பட்ட புற்களைப் போலானார்கள்; காற்று அவற்றை நாலாபுறமும் சிதறடித்தது.\" இப்னு ஸைத் (ரஹ்) கூறினார்கள்: \"அரபியர்கள் தங்களுடைய ஒட்டகங்கள் மற்றும் கால்நடைகளைச் சுற்றி காய்ந்த புதர்களைக் கொண்டு வேலிகளை (ஹிஸார் - இதிலிருந்தே 'அல்-முஹ்தழிர்' என்ற சொல் உருவானது) அமைப்பார்கள்; எனவே அல்லாஹ் கூறினான்,\" <span class=\"quran-arabic-font text-success\">﴾كَهَشِيمِ</span> <span class=\"quran-arabic-font text-success\">الْمُحْتَظِرِ﴿</span><br />\r\n<br />\r\n(வேலி அமைப்பவரின் காய்ந்த சருகுகளைப் போல.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">لِلذِّكْرِ</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ﴿</span><br />\r\n<br />\r\n(திண்ணமாக, நாம் இந்தக் குர்ஆனை (நினைவு கூர்வதற்காக) எளிதாக்கி வைத்துள்ளோம்; எனவே, (இதிலிருந்து) நல்லுணர்வு பெறுபவர் யாரேனும் உண்டா?) இதற்கான விளக்கத்தை ஏற்கனவே ஆரம்பத்தில் கண்டோம்.<br />\r\n<br />","text":"ஸமூது கூட்டத்தினரின் வரலாறு\n\r\n\n\r\nஸமூது சமூகத்தினர் தங்களுடைய தூதர் ஸாலிஹ் (அலை) அவர்களைப் பொய்ப்பித்ததாக அல்லாஹ் இங்கு கூறுகிறான், ﴾كَذَّبَتْ ثَمُودُ بِالنُّذُرِ ﴿ ﴾فَقَالُواْ أَبَشَرًا مِّنَّا وَاحِدًا نَّتَّبِعُهُ إِنَّآ إِذاً لَّفِى ضَلَـلٍ وَسُعُرٍ ﴿\n\r\n\n\r\n(மேலும் அவர்கள், \"நம்மில் ஒரு மனிதரையா நாம் பின்பற்றுவோம்? அவ்வாறாயின், நிச்சயமாக நாம் வழிகேட்டிலும், வேதனையிலும் இருப்போம்!\" என்று கூறினார்கள்.) 'நம்மில் ஒரு மனிதருக்கு நாம் அனைவரும் கட்டுப்பட்டால், நாம் தோல்வியையும் நஷ்டத்தையுமே அடைவோம்' என்று அவர்கள் கூறினார்கள். தங்களில் ஒருவருக்கு மட்டும் இந்த அறிவுரை (வஹீ) வழங்கப்பட்டதைக் கண்டு அவர்கள் ஆச்சரியமடைந்தனர்; அதனால் அவரைப் பொய்யர் என்று குற்றம் சுமத்தினர், ﴾أَءُلْقِىَ الذِّكْرُ عَلَيْهِ مِن بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ﴿\n\r\n\n\r\n(இல்லை, அவர் ஒரு திமிர் பிடித்த பொய்யர்!), அதாவது, அவர் தனது பொய்களில் வரம்பு மீறிவிட்டார் என்று அவர்கள் கருதினர். அதற்கு மிக உயர்ந்தவனான அல்லாஹ், ﴾سَيَعْلَمُونَ غَداً مَّنِ الْكَذَّابُ الْأَشِرُ ﴿\n\r\n\n\r\n(யார் அந்தத் திமிர் பிடித்த பொய்யர் என்பதை அவர்கள் நாளை அறிந்துகொள்வார்கள்!) என்று பதிலளித்தான். இதன் மூலம் அல்லாஹ் அவர்களை எச்சரித்து, அச்சுறுத்தி, ஒரு உறுதியான வாக்குறுதியையும் அளித்தான், ﴾إِنَّا مُرْسِلُواْ النَّاقَةِ فِتْنَةً لَّهُمْ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் அவர்களுக்குச் சோதனையாக ஒரு பெண் ஒட்டகத்தை அனுப்பப்போகிறோம்.) ஸமூது கூட்டத்தினரைச் சோதிப்பதற்காக, அவர்களின் கோரிக்கையின்படியே ஒரு திடமான பாறையிலிருந்து வெளிப்பட்ட ஒரு பிரம்மாண்டமான, சினை கொண்ட பெண் ஒட்டகத்தை அல்லாஹ் அவர்களுக்கு அனுப்பினான். அதன் பிறகு, அல்லாஹ்விடமிருந்து தங்களுக்கு வந்த ஒரு சான்றாக அதனை ஏற்று, ஸாலிஹ் (அலை) அவர்கள் கொண்டு வந்த செய்தியை அவர்கள் நம்ப வேண்டும் என்பதற்காகவே அவ்வாறு செய்தான். அல்லாஹ் தனது அடியாரும் தூதருமான ஸாலிஹ் (அலை) அவர்களுக்குக் கட்டளையிட்டான், ﴾فَارْتَقِبْهُمْ وَاصْطَبِرْ﴿\n\r\n\n\r\n(எனவே அவர்களைக் கவனித்துக்கொண்டிருப்பீராக, மேலும் பொறுமையைக் கடைப்பிடிப்பீராக!) அல்லாஹ் கட்டளையிட்டான், 'ஸாலிஹே! காத்திருப்பீராக, அவர்களுக்கு என்ன நேரிடும் என்று கவனிப்பீராக, மேலும் பொறுமையாக இருப்பீராக; நிச்சயமாகச் சிறந்த முடிவு உமக்கே உரியதாகும், மேலும் நீர் இம்மையிலும் மறுமையிலும் வெற்றி பெறுவீர்.' ﴾وَنَبِّئْهُمْ أَنَّ الْمَآءَ قِسْمَةٌ بَيْنَهُمْ﴿\n\r\n\n\r\n(மேலும் தண்ணீர் அவர்களுக்கிடையே பங்கிடப்பட வேண்டும் என்று அவர்களுக்குத் தெரிவிப்பீராக.) ஒரு நாள் அந்த ஒட்டகம் குடிப்பதற்கும், மற்றொரு நாள் மக்கள் குடிப்பதற்கும் என்று ஒதுக்கப்பட்டது, ﴾قَالَ هَـذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ ﴿\n\r\n\n\r\n(அவர் கூறினார்கள்: \"இதோ ஒரு பெண் ஒட்டகம்: அதற்கு ஒரு குறிப்பிட்ட நாளில் குடிப்பதற்கு உரிமை உண்டு, உங்களுக்கும் ஒரு குறிப்பிட்ட நாளில் குடிப்பதற்கு உரிமை உண்டு.\") (26:155) அல்லாஹ்வின் கூற்று, ﴾كُلُّ شِرْبٍ مُّحْتَضَرٌ﴿\n\r\n\n\r\n(ஒவ்வொருவரும் தங்களுக்குரிய முறைப்படி நீர் அருந்துவதற்கு ஆஜராக வேண்டும்.) முஜாஹித் (ரஹ்) கூறினார்கள்: \"அந்த ஒட்டகம் தண்ணீர் குடிக்காத நாட்களில் அவர்கள் தண்ணீரைப் பருகிக்கொள்வார்கள்; அது தண்ணீர் குடிக்கும் நாளில் அவர்கள் அதன் பாலைக் குடிப்பார்கள்.\" உயர்ந்தவனான அல்லாஹ் கூறினான்; ﴾فَنَادَوْاْ صَـحِبَهُمْ فَتَعَاطَى فَعَقَرَ ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் தங்கள் தோழனை அழைத்தார்கள்; அவன் (அதைப்) பிடித்து, அதன் கால்களை வெட்டிக் கொன்றான்.) தஃப்ஸீர் அறிஞர்களின் கூற்றுப்படி, அவனது பெயர் குதார் பின் ஸாலிஃப் ஆகும்; அவன் அந்த மக்களிடையே மிகவும் கொடியவனாக இருந்தான், ﴾إِذِ انبَعَثَ أَشْقَـهَا ﴿\n\r\n\n\r\n(அவர்களில் மிகவும் துர்ப்பாக்கியசாலி (அப்பெண் ஒட்டகத்தைக் கொல்ல) முன்வந்தபோது.) (91:12) அல்லாஹ் இங்கே கூறினான், ﴾فَتَعَاطَى﴿\n\r\n\n\r\n(மேலும் அவன் பிடித்தான்) அதாவது தீங்கு செய்யத் துணிந்தான், ﴾فَعَقَرَ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ ﴿\n\r\n\n\r\n(மேலும் (அவளை)க் கொன்றான். பிறகு, எனது வேதனையும் எனது எச்சரிக்கைகளும் எப்படி இருந்தன?) 'நான் அவர்களை வேதனை செய்தேன்; என்னை நிராகரித்ததாலும், எனது தூதரைப் பொய்ப்பித்ததாலும் நான் அவர்கள் மீது அனுப்பிய வேதனை எவ்வளவு கடுமையானதாக இருந்தது!' ﴾إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةً وَاحِدَةً فَكَانُواْ كَهَشِيمِ الْمُحْتَظِرِ ﴿\n\r\n\n\r\n(நிச்சயமாக நாம் அவர்கள் மீது ஒரேயொரு பேரொலியை (ஸய்ஹாவை) அனுப்பினோம்; அதனால் அவர்கள் வேலி அமைப்பவர் பயன்படுத்தும் காய்ந்த சருகுகளைப் போல் ஆகிவிட்டார்கள்.) அவர்கள் அனைவரும் அழிந்து போயினர்; அவர்களில் ஒருவரும் எஞ்சவில்லை. செடிகளும் புற்களும் காய்ந்து அழிந்து போவதைப் போல, அவர்களும் முற்றிலும் அழிந்து போயினர். அஸ்-ஸுத்தி (ரஹ்) கூறினார்கள்: \"அவர்கள் பாலைவனத்தில் காய்ந்து எரிக்கப்பட்ட புற்களைப் போலானார்கள்; காற்று அவற்றை நாலாபுறமும் சிதறடித்தது.\" இப்னு ஸைத் (ரஹ்) கூறினார்கள்: \"அரபியர்கள் தங்களுடைய ஒட்டகங்கள் மற்றும் கால்நடைகளைச் சுற்றி காய்ந்த புதர்களைக் கொண்டு வேலிகளை (ஹிஸார் - இதிலிருந்தே 'அல்-முஹ்தழிர்' என்ற சொல் உருவானது) அமைப்பார்கள்; எனவே அல்லாஹ் கூறினான்,\" ﴾كَهَشِيمِ الْمُحْتَظِرِ﴿\n\r\n\n\r\n(வேலி அமைப்பவரின் காய்ந்த சருகுகளைப் போல.)\n\r\n\n\r\n﴾وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ﴿\n\r\n\n\r\n(திண்ணமாக, நாம் இந்தக் குர்ஆனை (நினைவு கூர்வதற்காக) எளிதாக்கி வைத்துள்ளோம்; எனவே, (இதிலிருந்து) நல்லுணர்வு பெறுபவர் யாரேனும் உண்டா?) இதற்கான விளக்கத்தை ஏற்கனவே ஆரம்பத்தில் கண்டோம்."},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=40\" class=\"link\">54:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:40 ஐ பார்க்கவும்"},"40":{"html":"<strong>லூத் நபியின் சமூகத்தினரின் கதை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: லூத் (அலை) அவர்களின் சமூகத்தினர் தங்கள் தூதருக்கு மாறு செய்து, அவரைப் பொய்ப்பித்தனர். மேலும், மனித வரலாற்றில் இதற்கு முன் எவரும் செய்திராத ஓரினச்சேர்க்கை எனும் மிகக் கொடிய பாவத்தைச் செய்தார்கள். இதனால்தான், அல்லாஹ் அவர்களுக்கு முன் வாழ்ந்த எந்தச் சமுதாயத்திற்கும் அளிக்காத ஒரு தண்டனையைக் கொண்டு அவர்களை அழித்தான். ஜிப்ரீல் (அலை) அவர்களுக்கு, அவர்களின் ஊர்களை வானத்திற்கு உயர்த்தி, பிறகு அவற்றை அப்படியே அவர்கள் மீது தலைகீழாகக் கவிழ்த்துவிடுமாறும், அதன் மேல் அடையாளமிடப்பட்ட 'ஸிஜ்ஜில்' எனும் சுட்ட களிமண் கற்களைப் பொழியச் செய்யுமாறும் அல்லாஹ் கட்டளையிட்டான். எனவேதான் அல்லாஹ் இங்கே கூறினான்:<span class=\"quran-arabic-font text-success\">﴾إِنَّآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">حَاصِباً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">آلَ</span> <span class=\"quran-arabic-font text-success\">لُوطٍ</span> <span class=\"quran-arabic-font text-success\">نَّجَّيْنَاهُم</span> <span class=\"quran-arabic-font text-success\">بِسَحَرٍ﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக, நாம் அவர்கள் மீது கல்மழையை (ஹாஸிப்) அனுப்பினோம்; லூத்தின் குடும்பத்தினரைத் தவிர. அவர்களை இரவின் கடைசிப் பகுதியில் நாம் காப்பாற்றினோம்.\") அவர்கள் இரவின் இறுதிப் பகுதியில் அந்த ஊரை விட்டு வெளியேறினார்கள். லூத் (அலை) அவர்களை விசுவாசிக்காத அந்தச் சமூகத்தின் மீது இறங்கிய வேதனையிலிருந்து அவர்கள் காப்பாற்றப்பட்டார்கள். லூத் (அலை) அவர்களின் மனைவியும் அந்தச் சமூகத்தைச் சேர்ந்தவர்களுடன் அழிந்துபோனாள். அல்லாஹ்வின் தூதரான லூத் (அலை) அவர்கள் தனது மகள்களுடன் பாதுகாப்பாகவும் எவ்விதத் தீங்கும் இன்றியும் ஸதோமிலிருந்து வெளியேறினார்கள். அல்லாஹ் கூறினான்:<span class=\"quran-arabic-font text-success\">﴾نِعْمَةً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">عِندِنَا</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">نَجْزِى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">شَكَرَ</span> <span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَنذَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">بَطْشَتَنَا</span> <span class=\"quran-arabic-font text-success\">فَتَمَارَوْا</span> <span class=\"quran-arabic-font text-success\">بِالنُّذُرِ﴿</span><br />\r\n<br />\r\n(\"நம்மிடமிருந்துள்ள அருட்கொடையாக; நன்றி செலுத்துவோருக்கு இவ்வாறே நாம் நற்கூலி வழங்குகிறோம். நிச்சயமாக அவர் நமது தண்டனையைக் குறித்து அவர்களுக்கு எச்சரிக்கை செய்திருந்தார்; எனினும், அவர்கள் அந்த எச்சரிக்கைகள் குறித்து விவாதம் செய்தனர்.\") அதாவது, வேதனை வருவதற்கு முன்பே, அல்லாஹ்வின் தண்டனை மற்றும் வேதனையைக் குறித்து லூத் (அலை) அவர்கள் எச்சரித்தார்கள். ஆனால், அவர்கள் அந்த எச்சரிக்கைக்குச் செவிசாய்க்கவில்லை; மாறாக, அந்த எச்சரிக்கையைச் சந்தேகப்பட்டு விவாதித்தனர்.<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">رَاوَدُوهُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ضَيْفِهِ</span> <span class=\"quran-arabic-font text-success\">فَطَمَسْنَا</span> <span class=\"quran-arabic-font text-success\">أَعْيُنَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَذُوقُوا</span> <span class=\"quran-arabic-font text-success\">عَذَابِي</span> <span class=\"quran-arabic-font text-success\">وَنُذُرِ﴿</span><br />\r\n<br />\r\n(\"மேலும், அவர்கள் அவருடைய விருந்தினர்களை அடைய விரும்பினர் (அவமானப்படுத்த முயன்றனர்). ஆகவே, நாம் அவர்களின் கண்களைக் குருடாக்கினோம். 'எனவே, எனது வேதனையையும், எனது எச்சரிக்கையையும் சுவையுங்கள்!' (என்று கூறினோம்).\") ஜிப்ரீல், மீக்காயீல் மற்றும் இஸ்ராஃபீல் ஆகிய வானவர்கள் லூத் (அலை) அவர்களின் சமூகத்தைச் சோதிப்பதற்காக அழகான இளைஞர்களின் உருவத்தில் வந்த அன்றிரவு இது நடந்தது. லூத் (அலை) அவர்கள் தன் விருந்தினர்களை வரவேற்று உபசரித்தார்கள். ஆனால், தீயவளான அவருடைய மனைவியோ, லூத் (அலை) அவர்களின் இல்லத்திற்கு விருந்தினர்கள் வந்திருப்பதை தன் சமூகத்தாருக்குத் தெரியப்படுத்தினாள். அவர்கள் எல்லாத் திசைகளிலிருந்தும் அவசரமாகத் திரண்டு வந்தனர். லூத் (அலை) அவர்கள் கதவைச் சாத்திக் கொண்டு அவர்களைத் தடுக்க வேண்டியிருந்தது. அவர்கள் அன்றிரவு கதவை உடைக்க முயன்றனர். லூத் (அலை) அவர்கள் தன் விருந்தினர்களைக் காப்பாற்றப் போராடினார்கள்:<span class=\"quran-arabic-font text-success\">﴾هَـؤُلآءِ</span> <span class=\"quran-arabic-font text-success\">بَنَاتِى</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">فَـعِلِينَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் ஏதேனும் செய்வதாயிருந்தால் இதோ என் மகள்கள் இருக்கிறார்கள்\") (<a href=\"qurandisp.php?sura=15&ayah=71\" class=\"link\">15:71</a>). இது அந்தச் சமூகத்தின் பெண்களைக் குறிக்கிறது.<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">بَنَاتِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَقٍّ﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக உமது மகள்களிடம் எங்களுக்கு எந்தத் தேவையும் இல்லை என்பதை நீர் அறிவீர்!\") (<a href=\"qurandisp.php?sura=11&ayah=79\" class=\"link\">11:79</a>). அதாவது, 'எங்களுக்குப் பெண்கள் மீது விருப்பமில்லை' என்பதாகும்.<span class=\"quran-arabic-font text-success\">﴾وَإِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَتَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نُرِيدُ﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக நாம் என்ன நாடுகிறோம் என்பதையும் நீர் அறிவீர்!\") (<a href=\"qurandisp.php?sura=11&ayah=79\" class=\"link\">11:79</a>). நிலைமை விபரீதமானபோது, அவர்கள் உள்ளே நுழையப் பிடிவாதம் பிடித்தனர். அப்போது ஜிப்ரீல் (அலை) அவர்கள் வெளியே வந்து, தனது இறக்கையின் நுனியால் அவர்களுடைய கண்களில் அடித்தார்கள். இதனால் அவர்கள் கண் பார்வையை இழந்தார்கள். அவர்கள் சுவர்களைத் தடவிப் பார்த்துக் கொண்டே தட்டுத்தடுமாறித் திரும்பிச் சென்றார்கள். விடியற்காலையில் லூத் (அலை) அவர்களுக்கு என்ன நேரிடும் என்று அவரை மிரட்டிச் சென்றார்கள். அல்லாஹ் கூறினான்:<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَبَّحَهُم</span> <span class=\"quran-arabic-font text-success\">بُكْرَةً</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِرٌّ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக, விடியற்காலையில் ஒரு நிலையான வேதனை அவர்களைப் பிடித்துக்கொண்டது.\") அதாவது, அவர்களால் தப்பிக்கவோ அல்லது தவிர்க்கவோ முடியாத ஒரு தண்டனை அவர்களைத் தாக்கியது.<span class=\"quran-arabic-font text-success\">﴾فَذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">عَذَابِى</span> <span class=\"quran-arabic-font text-success\">وَنُذُرِ</span> <span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">يَسَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">لِلذِّكْرِ</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"ஆகவே, எனது வேதனையையும் எனது எச்சரிக்கைகளையும் சுவையுங்கள்! நிச்சயமாக, நாம் இந்தக் குர்ஆனை நினைவுகூர்வதற்கு எளிதாக்கினோம். ஆகவே, நினைவுகூருபவர் எவருமுண்டா?\")<br />\r\n<br />","text":"லூத் நபியின் சமூகத்தினரின் கதை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: லூத் (அலை) அவர்களின் சமூகத்தினர் தங்கள் தூதருக்கு மாறு செய்து, அவரைப் பொய்ப்பித்தனர். மேலும், மனித வரலாற்றில் இதற்கு முன் எவரும் செய்திராத ஓரினச்சேர்க்கை எனும் மிகக் கொடிய பாவத்தைச் செய்தார்கள். இதனால்தான், அல்லாஹ் அவர்களுக்கு முன் வாழ்ந்த எந்தச் சமுதாயத்திற்கும் அளிக்காத ஒரு தண்டனையைக் கொண்டு அவர்களை அழித்தான். ஜிப்ரீல் (அலை) அவர்களுக்கு, அவர்களின் ஊர்களை வானத்திற்கு உயர்த்தி, பிறகு அவற்றை அப்படியே அவர்கள் மீது தலைகீழாகக் கவிழ்த்துவிடுமாறும், அதன் மேல் அடையாளமிடப்பட்ட 'ஸிஜ்ஜில்' எனும் சுட்ட களிமண் கற்களைப் பொழியச் செய்யுமாறும் அல்லாஹ் கட்டளையிட்டான். எனவேதான் அல்லாஹ் இங்கே கூறினான்:﴾إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِباً إِلاَّ آلَ لُوطٍ نَّجَّيْنَاهُم بِسَحَرٍ﴿\n\r\n\n\r\n(\"நிச்சயமாக, நாம் அவர்கள் மீது கல்மழையை (ஹாஸிப்) அனுப்பினோம்; லூத்தின் குடும்பத்தினரைத் தவிர. அவர்களை இரவின் கடைசிப் பகுதியில் நாம் காப்பாற்றினோம்.\") அவர்கள் இரவின் இறுதிப் பகுதியில் அந்த ஊரை விட்டு வெளியேறினார்கள். லூத் (அலை) அவர்களை விசுவாசிக்காத அந்தச் சமூகத்தின் மீது இறங்கிய வேதனையிலிருந்து அவர்கள் காப்பாற்றப்பட்டார்கள். லூத் (அலை) அவர்களின் மனைவியும் அந்தச் சமூகத்தைச் சேர்ந்தவர்களுடன் அழிந்துபோனாள். அல்லாஹ்வின் தூதரான லூத் (அலை) அவர்கள் தனது மகள்களுடன் பாதுகாப்பாகவும் எவ்விதத் தீங்கும் இன்றியும் ஸதோமிலிருந்து வெளியேறினார்கள். அல்லாஹ் கூறினான்:﴾نِعْمَةً مِّنْ عِندِنَا كَذَلِكَ نَجْزِى مَن شَكَرَ وَلَقَدْ أَنذَرَهُمْ بَطْشَتَنَا فَتَمَارَوْا بِالنُّذُرِ﴿\n\r\n\n\r\n(\"நம்மிடமிருந்துள்ள அருட்கொடையாக; நன்றி செலுத்துவோருக்கு இவ்வாறே நாம் நற்கூலி வழங்குகிறோம். நிச்சயமாக அவர் நமது தண்டனையைக் குறித்து அவர்களுக்கு எச்சரிக்கை செய்திருந்தார்; எனினும், அவர்கள் அந்த எச்சரிக்கைகள் குறித்து விவாதம் செய்தனர்.\") அதாவது, வேதனை வருவதற்கு முன்பே, அல்லாஹ்வின் தண்டனை மற்றும் வேதனையைக் குறித்து லூத் (அலை) அவர்கள் எச்சரித்தார்கள். ஆனால், அவர்கள் அந்த எச்சரிக்கைக்குச் செவிசாய்க்கவில்லை; மாறாக, அந்த எச்சரிக்கையைச் சந்தேகப்பட்டு விவாதித்தனர்.﴾وَلَقَدْ رَاوَدُوهُ عَن ضَيْفِهِ فَطَمَسْنَا أَعْيُنَهُمْ فَذُوقُوا عَذَابِي وَنُذُرِ﴿\n\r\n\n\r\n(\"மேலும், அவர்கள் அவருடைய விருந்தினர்களை அடைய விரும்பினர் (அவமானப்படுத்த முயன்றனர்). ஆகவே, நாம் அவர்களின் கண்களைக் குருடாக்கினோம். 'எனவே, எனது வேதனையையும், எனது எச்சரிக்கையையும் சுவையுங்கள்!' (என்று கூறினோம்).\") ஜிப்ரீல், மீக்காயீல் மற்றும் இஸ்ராஃபீல் ஆகிய வானவர்கள் லூத் (அலை) அவர்களின் சமூகத்தைச் சோதிப்பதற்காக அழகான இளைஞர்களின் உருவத்தில் வந்த அன்றிரவு இது நடந்தது. லூத் (அலை) அவர்கள் தன் விருந்தினர்களை வரவேற்று உபசரித்தார்கள். ஆனால், தீயவளான அவருடைய மனைவியோ, லூத் (அலை) அவர்களின் இல்லத்திற்கு விருந்தினர்கள் வந்திருப்பதை தன் சமூகத்தாருக்குத் தெரியப்படுத்தினாள். அவர்கள் எல்லாத் திசைகளிலிருந்தும் அவசரமாகத் திரண்டு வந்தனர். லூத் (அலை) அவர்கள் கதவைச் சாத்திக் கொண்டு அவர்களைத் தடுக்க வேண்டியிருந்தது. அவர்கள் அன்றிரவு கதவை உடைக்க முயன்றனர். லூத் (அலை) அவர்கள் தன் விருந்தினர்களைக் காப்பாற்றப் போராடினார்கள்:﴾هَـؤُلآءِ بَنَاتِى إِن كُنْتُمْ فَـعِلِينَ﴿\n\r\n\n\r\n(\"நீங்கள் ஏதேனும் செய்வதாயிருந்தால் இதோ என் மகள்கள் இருக்கிறார்கள்\") (15:71). இது அந்தச் சமூகத்தின் பெண்களைக் குறிக்கிறது.﴾قَالُواْ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக உமது மகள்களிடம் எங்களுக்கு எந்தத் தேவையும் இல்லை என்பதை நீர் அறிவீர்!\") (11:79). அதாவது, 'எங்களுக்குப் பெண்கள் மீது விருப்பமில்லை' என்பதாகும்.﴾وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ﴿\n\r\n\n\r\n(\"நிச்சயமாக நாம் என்ன நாடுகிறோம் என்பதையும் நீர் அறிவீர்!\") (11:79). நிலைமை விபரீதமானபோது, அவர்கள் உள்ளே நுழையப் பிடிவாதம் பிடித்தனர். அப்போது ஜிப்ரீல் (அலை) அவர்கள் வெளியே வந்து, தனது இறக்கையின் நுனியால் அவர்களுடைய கண்களில் அடித்தார்கள். இதனால் அவர்கள் கண் பார்வையை இழந்தார்கள். அவர்கள் சுவர்களைத் தடவிப் பார்த்துக் கொண்டே தட்டுத்தடுமாறித் திரும்பிச் சென்றார்கள். விடியற்காலையில் லூத் (அலை) அவர்களுக்கு என்ன நேரிடும் என்று அவரை மிரட்டிச் சென்றார்கள். அல்லாஹ் கூறினான்:﴾وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌ مُّسْتَقِرٌّ ﴿\n\r\n\n\r\n(\"நிச்சயமாக, விடியற்காலையில் ஒரு நிலையான வேதனை அவர்களைப் பிடித்துக்கொண்டது.\") அதாவது, அவர்களால் தப்பிக்கவோ அல்லது தவிர்க்கவோ முடியாத ஒரு தண்டனை அவர்களைத் தாக்கியது.﴾فَذُوقُواْ عَذَابِى وَنُذُرِ وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ ﴿\n\r\n\n\r\n(\"ஆகவே, எனது வேதனையையும் எனது எச்சரிக்கைகளையும் சுவையுங்கள்! நிச்சயமாக, நாம் இந்தக் குர்ஆனை நினைவுகூர்வதற்கு எளிதாக்கினோம். ஆகவே, நினைவுகூருபவர் எவருமுண்டா?\")"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=46\" class=\"link\">54:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:46 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=46\" class=\"link\">54:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:46 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=46\" class=\"link\">54:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:46 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=46\" class=\"link\">54:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:46 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=46\" class=\"link\">54:46</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:46 ஐ பார்க்கவும்"},"46":{"html":"<strong>ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரின் வரலாறு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَاءَ</span> <span class=\"quran-arabic-font text-success\">آلَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">النُّذُرُ</span> - <span class=\"quran-arabic-font text-success\">كَذَّبُوا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">كُلِّهَا</span> <span class=\"quran-arabic-font text-success\">فَأَخَذْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">أَخْذَ</span> <span class=\"quran-arabic-font text-success\">عَزِيزٍ</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدِرٍ</span><br />\r\n<br />\r\nஉயர்ந்தோனாகிய அல்லாஹ், ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரைப் பற்றிய வரலாற்றை நமக்கு விவரிக்கிறான். அவர்களிடம் அல்லாஹ்விடமிருந்து ஒரு தூதர் வந்தார்; அவர்தான் மூஸா (அலை). அவருக்குத் துணையாக அவரது சகோதரர் ஹாரூன் (அலை) அவர்கள் இருந்தார்கள். அவர்கள் ஈமான் கொண்டால் (நம்பிக்கை கொண்டால்) நற்செய்தியையும், அச்செய்தியை நிராகரித்தால் எச்சரிக்கையையும் அத்தூதர்கள் வழங்கினார்கள். அல்லாஹ் மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோருக்குப் பிரம்மாண்டமான அற்புதங்களையும் மகத்தான அத்தாட்சிகளையும் வழங்கி அவர்களுக்கு உதவினான். ஆனால், ஃபிர்அவ்னும் அவனது கூட்டத்தாரும் அவை அனைத்தையும் நிராகரித்தனர். எனவே, யாவற்றையும் மிகைத்தவனும் பேராற்றல் மிக்கவனுமான அல்லாஹ் அவர்களைத் தனது பிடியில் ஆழ்த்தினான்; அவர்களுக்கு என்ன நேர்ந்தது என்பதை எடுத்துச் சொல்ல ஒருவரும் எஞ்சாதவாறு அல்லாஹ் அவர்கள் அனைவரையும் அழித்தான். குரைஷிகளுக்கு அறிவுரை கூறியும் அவர்களை எச்சரித்தும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَكُفَّارُكُمْ</span><br />\r\n<br />\r\n(உங்களிலுள்ள நிராகரிப்பாளர்களா?) அதாவது, \"குரைஷிகளின் விக்கிரக ஆராதனைக்காரர்களே!\" என்று பொருள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكُمْ</span><br />\r\n<br />\r\n(இவர்களை விடச் சிறந்தவர்களா?) அதாவது, தூதர்களை நம்ப மறுத்ததாலும் வேதங்களை நிராகரித்ததாலும் இங்கே குறிப்பிடப்பட்டு அழிக்கப்பட்ட சமுதாயங்களை விட இவர்கள் சிறந்தவர்களா? \"நீங்கள் இவர்களை விடச் சிறந்தவர்களா?\" (என்பது இதன் கருத்தாகும்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَكُم</span> <span class=\"quran-arabic-font text-success\">بَرَآءَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الزُّبُرِ</span><br />\r\n<br />\r\n(அல்லது வேதங்களில் உங்களுக்கு ஏதேனும் விலக்கு அளிக்கப்பட்டுள்ளதா?), 'வேதனையும் தண்டனையும் உங்களைத் தீண்டாது என்று அல்லாஹ்விடமிருந்து ஏதேனும் பாதுகாப்புறுதி உங்களுக்கு இருக்கிறதா?' குரைஷிகளைப் பற்றி அல்லாஹ் (மேலும்) கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">جَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">مُّنتَصِرٌ</span><br />\r\n<br />\r\n(அல்லது அவர்கள்: \"நாங்கள் ஒரு மாபெரும் கூட்டம், வெற்றி பெறுவோம்\" என்று கூறுகிறார்களா?) தங்களுக்குள் ஒருவருக்கொருவர் ஆதரவாக இருப்போம் என்றும், தங்களுக்குத் தீங்கு செய்ய நினைப்பவர்களுக்கு எதிராகத் தங்களின் பெரும் கூட்டம் தங்களுக்குப் பாதுகாப்பாக அமையும் என்றும் அவர்கள் நம்பியதை இது குறிக்கிறது. இதற்கு உயர்ந்தோனாகிய அல்லாஹ் பதிலளித்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيُهْزَمُ</span> <span class=\"quran-arabic-font text-success\">الْجَمْعُ</span> <span class=\"quran-arabic-font text-success\">وَيُوَلُّونَ</span> <span class=\"quran-arabic-font text-success\">الدُّبُرَ</span><br />\r\n<br />\r\n(அக்கூட்டம் விரைவில் தோற்கடிக்கப்படும்; அவர்கள் புறமுதுகு காட்டி ஓடுவார்கள்.) அவர்களுடைய கூட்டம் சிதறடிக்கப்பட்டு அவர்கள் தோற்கடிக்கப்படுவார்கள் என்பதை இது உறுதிப்படுத்துகிறது.<br />\r\n<br />\r\nஇக்ரிமா (ரஹ்) அவர்கள் கூறினார்கள்: இந்த வசனம் அருளப்பட்டபோது உமர் (ரழி) அவர்கள், “எந்தக் கூட்டம் தோற்கடிக்கப்படும்? எந்தக் கூட்டம் விரட்டி அடிக்கப்படும்?” என்று கேட்டார்கள். பத்ருப் போர் நாளில் நபி (ஸல்) அவர்கள் “ஸயுஹ்ஸமுல் ஜம்உ வயுவல்லூனத் துபுர்” என்று ஓதியதைக் கேட்ட பிறகுதான் இதன் விளக்கத்தை நான் அறிந்து கொண்டேன் என்று உமர் (ரழி) கூறினார்கள்.<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் புகாரி பதிவு செய்துள்ளார்கள்: பத்ருப் போர் நடைபெற்ற நாளில் நபி (ஸல்) அவர்கள் ஒரு கூடாரத்தில் இருந்தபோது பின்வருமாறு பிரார்த்தித்தார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْشُدُكَ</span> <span class=\"quran-arabic-font text-success\">عَهْدَكَ</span> <span class=\"quran-arabic-font text-success\">وَوَعْدَكَ،</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">شِئْتَ</span> <span class=\"quran-arabic-font text-success\">لَنْ</span> <span class=\"quran-arabic-font text-success\">تُعْبَدْ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَبَدًا</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! உன்னுடைய உடன்படிக்கையையும் வாக்குறுதியையும் நிறைவேற்றுமாறு உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! நீ (இந்த முஃமின்களை அழிக்க) நாடினால், இன்றைய தினத்திற்குப் பிறகு இப்பூமியில் நீ ஒருபோதும் வணங்கப்பட மாட்டாய்.) அப்போது அபூபக்ர் (ரழி) அவர்கள் நபி (ஸல்) அவர்களின் கையைப் பிடித்துக் கொண்டு, \"அல்லாஹ்வின் தூதரே! இது போதும். நீங்கள் அல்லாஹ்விடம் போதுமான அளவு கெஞ்சிப் பிரார்த்தித்துவிட்டீர்கள்\" என்று கூறினார்கள். அப்போது கவச உடை அணிந்திருந்த நபி (ஸல்) அவர்கள், பின்வரும் வசனத்தை ஓதியவாறு வெளியே வந்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَيُهْزَمُ</span> <span class=\"quran-arabic-font text-success\">الْجَمْعُ</span> <span class=\"quran-arabic-font text-success\">وَيُوَلُّونَ</span> <span class=\"quran-arabic-font text-success\">الدُّبُرَ</span><br />\r\n<br />\r\n(அக்கூட்டம் விரைவில் தோற்கடிக்கப்பட்டு, அவர்கள் புறமுதுகு காட்டி ஓடுவார்கள்.)<br />\r\n<br />\r\nயூசுஃப் பின் மஹக் அவர்கள் கூறியதாகப் புகாரி பதிவு செய்துள்ளார்கள்: \"நான் இறைநம்பிக்கையாளர்களின் தாயார் ஆயிஷா (ரழி) அவர்களுடன் இருந்தபோது அவர்கள் கூறினார்கள்: 'நான் மக்காவில் விளையாடிக் கொண்டிருந்த சிறுமியாக இருந்தபோதே முஹம்மது (ஸல்) அவர்களுக்கு இந்த வசனம் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلِ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">مَوْعِدُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَالسَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">أَدْهَى</span> <span class=\"quran-arabic-font text-success\">وَأَمَرُّ</span><br />\r\n<br />\r\n(மாறாக, மறுமை நேரமே அவர்களுக்கு வாக்களிக்கப்பட்ட நேரமாகும்; அந்த நேரம் மிகவும் கொடியதும் மிகவும் கசப்பானதுமாகும்.)\" இது புகாரியில் இடம்பெற்றுள்ள ஒரு சுருக்கமான அறிவிப்பாகும். புகாரி அவர்கள் 'குர்ஆனின் சிறப்புகள்' என்ற அத்தியாயத்தில் இதன் விரிவான அறிவிப்பையும் பதிவு செய்துள்ளார்கள். இமாம் முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்யவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">وَسُعُرٍ</span> - <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span><br />\r\n<br />\r\n(நிச்சயமாகக் குற்றவாளிகள் வழிகேட்டிலும், (நரக) நெருப்பிலும் இருக்கின்றனர். அவர்கள் தங்கள் முகங்கள் குப்புற நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில், \"ஸகர் (நரகத்)தின் வேதனையைச் சுவைத்துப் பாருங்கள்\" (என்று அவர்களுக்குச் சொல்லப்படும்).)<br />\r\n<br />","text":"ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரின் வரலாறு\n\r\n\n\r\nوَلَقَدْ جَاءَ آلَ فِرْعَوْنَ النُّذُرُ - كَذَّبُوا بِآيَاتِنَا كُلِّهَا فَأَخَذْنَاهُمْ أَخْذَ عَزِيزٍ مُّقْتَدِرٍ\n\r\n\n\r\nஉயர்ந்தோனாகிய அல்லாஹ், ஃபிர்அவ்ன் மற்றும் அவனது கூட்டத்தாரைப் பற்றிய வரலாற்றை நமக்கு விவரிக்கிறான். அவர்களிடம் அல்லாஹ்விடமிருந்து ஒரு தூதர் வந்தார்; அவர்தான் மூஸா (அலை). அவருக்குத் துணையாக அவரது சகோதரர் ஹாரூன் (அலை) அவர்கள் இருந்தார்கள். அவர்கள் ஈமான் கொண்டால் (நம்பிக்கை கொண்டால்) நற்செய்தியையும், அச்செய்தியை நிராகரித்தால் எச்சரிக்கையையும் அத்தூதர்கள் வழங்கினார்கள். அல்லாஹ் மூஸா (அலை) மற்றும் ஹாரூன் (அலை) ஆகியோருக்குப் பிரம்மாண்டமான அற்புதங்களையும் மகத்தான அத்தாட்சிகளையும் வழங்கி அவர்களுக்கு உதவினான். ஆனால், ஃபிர்அவ்னும் அவனது கூட்டத்தாரும் அவை அனைத்தையும் நிராகரித்தனர். எனவே, யாவற்றையும் மிகைத்தவனும் பேராற்றல் மிக்கவனுமான அல்லாஹ் அவர்களைத் தனது பிடியில் ஆழ்த்தினான்; அவர்களுக்கு என்ன நேர்ந்தது என்பதை எடுத்துச் சொல்ல ஒருவரும் எஞ்சாதவாறு அல்லாஹ் அவர்கள் அனைவரையும் அழித்தான். குரைஷிகளுக்கு அறிவுரை கூறியும் அவர்களை எச்சரித்தும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nأَكُفَّارُكُمْ\n\r\n\n\r\n(உங்களிலுள்ள நிராகரிப்பாளர்களா?) அதாவது, \"குரைஷிகளின் விக்கிரக ஆராதனைக்காரர்களே!\" என்று பொருள்.\n\r\n\n\r\nخَيْرٌ مِّنْ أُولَئِكُمْ\n\r\n\n\r\n(இவர்களை விடச் சிறந்தவர்களா?) அதாவது, தூதர்களை நம்ப மறுத்ததாலும் வேதங்களை நிராகரித்ததாலும் இங்கே குறிப்பிடப்பட்டு அழிக்கப்பட்ட சமுதாயங்களை விட இவர்கள் சிறந்தவர்களா? \"நீங்கள் இவர்களை விடச் சிறந்தவர்களா?\" (என்பது இதன் கருத்தாகும்).\n\r\n\n\r\nأَمْ لَكُم بَرَآءَةٌ فِى الزُّبُرِ\n\r\n\n\r\n(அல்லது வேதங்களில் உங்களுக்கு ஏதேனும் விலக்கு அளிக்கப்பட்டுள்ளதா?), 'வேதனையும் தண்டனையும் உங்களைத் தீண்டாது என்று அல்லாஹ்விடமிருந்து ஏதேனும் பாதுகாப்புறுதி உங்களுக்கு இருக்கிறதா?' குரைஷிகளைப் பற்றி அல்லாஹ் (மேலும்) கூறினான்:\n\r\n\n\r\nأَمْ يَقُولُونَ نَحْنُ جَمِيعٌ مُّنتَصِرٌ\n\r\n\n\r\n(அல்லது அவர்கள்: \"நாங்கள் ஒரு மாபெரும் கூட்டம், வெற்றி பெறுவோம்\" என்று கூறுகிறார்களா?) தங்களுக்குள் ஒருவருக்கொருவர் ஆதரவாக இருப்போம் என்றும், தங்களுக்குத் தீங்கு செய்ய நினைப்பவர்களுக்கு எதிராகத் தங்களின் பெரும் கூட்டம் தங்களுக்குப் பாதுகாப்பாக அமையும் என்றும் அவர்கள் நம்பியதை இது குறிக்கிறது. இதற்கு உயர்ந்தோனாகிய அல்லாஹ் பதிலளித்தான்:\n\r\n\n\r\nسَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ\n\r\n\n\r\n(அக்கூட்டம் விரைவில் தோற்கடிக்கப்படும்; அவர்கள் புறமுதுகு காட்டி ஓடுவார்கள்.) அவர்களுடைய கூட்டம் சிதறடிக்கப்பட்டு அவர்கள் தோற்கடிக்கப்படுவார்கள் என்பதை இது உறுதிப்படுத்துகிறது.\n\r\n\n\r\nஇக்ரிமா (ரஹ்) அவர்கள் கூறினார்கள்: இந்த வசனம் அருளப்பட்டபோது உமர் (ரழி) அவர்கள், “எந்தக் கூட்டம் தோற்கடிக்கப்படும்? எந்தக் கூட்டம் விரட்டி அடிக்கப்படும்?” என்று கேட்டார்கள். பத்ருப் போர் நாளில் நபி (ஸல்) அவர்கள் “ஸயுஹ்ஸமுல் ஜம்உ வயுவல்லூனத் துபுர்” என்று ஓதியதைக் கேட்ட பிறகுதான் இதன் விளக்கத்தை நான் அறிந்து கொண்டேன் என்று உமர் (ரழி) கூறினார்கள்.\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் புகாரி பதிவு செய்துள்ளார்கள்: பத்ருப் போர் நடைபெற்ற நாளில் நபி (ஸல்) அவர்கள் ஒரு கூடாரத்தில் இருந்தபோது பின்வருமாறு பிரார்த்தித்தார்கள்:\n\r\n\n\r\n«أَنْشُدُكَ عَهْدَكَ وَوَعْدَكَ، اللَّهُمَّ إِنْ شِئْتَ لَنْ تُعْبَدْ بَعْدَ الْيَوْمِ فِي الْأَرْضِ أَبَدًا»\n\r\n\n\r\n(யா அல்லாஹ்! உன்னுடைய உடன்படிக்கையையும் வாக்குறுதியையும் நிறைவேற்றுமாறு உன்னிடம் வேண்டுகிறேன். யா அல்லாஹ்! நீ (இந்த முஃமின்களை அழிக்க) நாடினால், இன்றைய தினத்திற்குப் பிறகு இப்பூமியில் நீ ஒருபோதும் வணங்கப்பட மாட்டாய்.) அப்போது அபூபக்ர் (ரழி) அவர்கள் நபி (ஸல்) அவர்களின் கையைப் பிடித்துக் கொண்டு, \"அல்லாஹ்வின் தூதரே! இது போதும். நீங்கள் அல்லாஹ்விடம் போதுமான அளவு கெஞ்சிப் பிரார்த்தித்துவிட்டீர்கள்\" என்று கூறினார்கள். அப்போது கவச உடை அணிந்திருந்த நபி (ஸல்) அவர்கள், பின்வரும் வசனத்தை ஓதியவாறு வெளியே வந்தார்கள்:\n\r\n\n\r\nسَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ\n\r\n\n\r\n(அக்கூட்டம் விரைவில் தோற்கடிக்கப்பட்டு, அவர்கள் புறமுதுகு காட்டி ஓடுவார்கள்.)\n\r\n\n\r\nயூசுஃப் பின் மஹக் அவர்கள் கூறியதாகப் புகாரி பதிவு செய்துள்ளார்கள்: \"நான் இறைநம்பிக்கையாளர்களின் தாயார் ஆயிஷா (ரழி) அவர்களுடன் இருந்தபோது அவர்கள் கூறினார்கள்: 'நான் மக்காவில் விளையாடிக் கொண்டிருந்த சிறுமியாக இருந்தபோதே முஹம்மது (ஸல்) அவர்களுக்கு இந்த வசனம் வஹீயாக (இறைச்செய்தியாக) அருளப்பட்டது:\n\r\n\n\r\nبَلِ السَّاعَةُ مَوْعِدُهُمْ وَالسَّاعَةُ أَدْهَى وَأَمَرُّ\n\r\n\n\r\n(மாறாக, மறுமை நேரமே அவர்களுக்கு வாக்களிக்கப்பட்ட நேரமாகும்; அந்த நேரம் மிகவும் கொடியதும் மிகவும் கசப்பானதுமாகும்.)\" இது புகாரியில் இடம்பெற்றுள்ள ஒரு சுருக்கமான அறிவிப்பாகும். புகாரி அவர்கள் 'குர்ஆனின் சிறப்புகள்' என்ற அத்தியாயத்தில் இதன் விரிவான அறிவிப்பையும் பதிவு செய்துள்ளார்கள். இமாம் முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்யவில்லை.\n\r\n\n\r\nإِنَّ الْمُجْرِمِينَ فِي ضَلَالٍ وَسُعُرٍ - يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ\n\r\n\n\r\n(நிச்சயமாகக் குற்றவாளிகள் வழிகேட்டிலும், (நரக) நெருப்பிலும் இருக்கின்றனர். அவர்கள் தங்கள் முகங்கள் குப்புற நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில், \"ஸகர் (நரகத்)தின் வேதனையைச் சுவைத்துப் பாருங்கள்\" (என்று அவர்களுக்குச் சொல்லப்படும்).)"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=54&ayah=55\" class=\"link\">54:55</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 54:55 ஐ பார்க்கவும்"},"55":{"html":"<strong>குற்றவாளிகளின் முடிவு</strong><br />\r\n<br />\r\nகண்ணியமிக்க அல்லாஹ் கூறுகிறான், குற்றவாளிகள் சத்தியத்தை விட்டு வழிதவறி, தங்களின் சந்தேகங்கள் மற்றும் தடுமாற்றங்களின் காரணமாக குழப்பத்தில் மூழ்கியுள்ளனர். இந்தப் பண்பு, அனைத்து வகையான பிரிவுகளைச் சார்ந்த ஒவ்வொரு நிராகரிப்பாளருக்கும் மற்றும் மார்க்கத்தில் புதுமையைப் புகுத்துபவர்களுக்கும் பொருந்தும். கண்ணியமிக்க அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்), அதாவது, அவர்கள் எவ்வாறு சந்தேகத்திலும் தயக்கத்திலும் மூழ்கியிருந்தார்களோ, அவ்வாறே நரக நெருப்பில் வீழ்வார்கள். அவர்கள் நேர்வழி தவறி வாழ்ந்ததைப் போலவே, தாங்கள் எங்கு கொண்டு செல்லப்படுகிறோம் என்பதை அறியாத நிலையில் முகங்கள் குப்புற இழுத்துச் செல்லப்படுவார்கள். அவர்கள் கண்டிக்கப்பட்டு இவ்வாறு கூறப்படுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span><br />\r\n<br />\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\")<br />\r\n<br />\r\n<strong>அனைத்தும் விதியுடன் (கத்ருடன்) படைக்கப்பட்டுள்ளன</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் இக்கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) என்பது மற்ற பல வசனங்களைப் போன்றதே ஆகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَخَلَقَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">فَقَدَّرَهُ</span> <span class=\"quran-arabic-font text-success\">تَقْدِيرًا</span><br />\r\n<br />\r\n(அவன் ஒவ்வொரு பொருளையும் படைத்து, அதற்கென ஒரு விதியைத் துல்லியமாக நிர்ணயித்தான் (ஃபகத்தரஹு தக்தீரா).) (<a href=\"qurandisp.php?sura=25&ayah=2\" class=\"link\">25:2</a>) மற்றும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَبِّحِ</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span> - <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">فَسَوَّى</span> - <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">فَهَدَى</span><br />\r\n<br />\r\n(உமது மிக உயர்ந்த இறைவனின் திருநாமத்தைத் துதிப்பீராக! அவன் (யாவற்றையும்) படைத்துச் சீராக்கினான். மேலும் அவன் (அனைத்தையும்) நிர்ணயித்து (கத்தர), பின்னர் வழிகாட்டினான்.) (<a href=\"qurandisp.php?sura=87&ayah=1\" class=\"link\">87:1</a>-3), அதாவது, அவன் ஒவ்வொரு பொருளின் மொத்த அளவையும் (கத்ரையும்) நிர்ணயித்து, படைப்புகளை அதன்பால் வழிநடத்தினான். படைப்புகள் உருவாக்கப்படுவதற்கு முன்பே அவற்றுக்கான விதிகளை அல்லாஹ் நிர்ணயித்துவிட்டான் என்பதற்கு சுன்னாவின் இமாம்கள் இந்த கண்ணியமிக்க வசனத்தை ஆதாரமாகக் கொள்கின்றனர். ஒவ்வொன்றும் நடப்பதற்கு முன்பே அது குறித்து அல்லாஹ் அறிந்திருந்தான்; மேலும் அவை நிகழ்வதற்கு முன்பே அனைத்தையும் பதிவு செய்துவிட்டான். ஸஹாபாக்களின் (ரழி) இறுதிக் காலத்தில் தோன்றிய 'கத்ரிய்யா' (விதியை மறுப்பவர்) பிரிவினரை மறுப்பதற்காக, அறிஞர்கள் இந்த வசனத்தையும், இது போன்ற பிற வசனங்களையும் ஹதீஸ்களையும் பயன்படுத்தினார்கள். இக்கருத்தைப் பற்றி ஸஹீஹ் அல்-புகாரியின் ஈமான் (நம்பிக்கை) அத்தியாயத்திற்கான எனது விளக்கவுரையில் விரிவாகக் குறிப்பிட்டுள்ளேன். இந்த வசனம் தொடர்பான சில ஹதீஸ்களை இங்கே குறிப்பிடுகிறேன். இமாம் அஹ்மத் அவர்கள் அபூஹுரைரா (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: \"குறைஷி இணைவைப்பாளர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து விதியைப் (கத்ர்) பற்றி விவாதித்து அதை மறுத்தார்கள். அப்போது இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்: \"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.)\" முஸ்லிம், திர்மிதி மற்றும் இப்னு மாஜா ஆகியோரும் இந்த ஹதீஸைப் பதிவுசெய்துள்ளனர். அல்-பஸ்ஸார் அவர்கள் அம்ர் பின் ஷுஐப் தனது தந்தை மற்றும் பாட்டனார் வழியாகக் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: \"இந்த வசனங்கள் விதியை (கத்ர்) மறுப்பவர்களைப் பற்றி அருளப்பட்டன:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">وَسُعُرٍ</span> - <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(நிச்சயமாக, குற்றவாளிகள் வழிகேட்டிலும் நரக நெருப்பிலுமே இருப்பார்கள். அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்: \"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.)\" இப்னு அபீ ஹாதிம் அவர்கள் ஸுராரா தனது தந்தை வழியாகக் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) பின்னர் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَزَلَتْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُنَاسٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">يَكُونُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">آخِرِ</span> <span class=\"quran-arabic-font text-success\">الزَّمَانِ</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرِ</span> <span class=\"quran-arabic-font text-success\">الله</span>»<br />\r\n<br />\r\n(இந்த வசனங்கள் என் உம்மத்தைச் சேர்ந்த சிலரைப் பற்றி அருளப்பட்டன. அவர்கள் இறுதி காலத்தில் தோன்றி அல்லாஹ்வின் விதியைப் (கத்ர்) பொய்யாக்குவார்கள்.) அதாஃ பின் அபீ ரபாஹ் அவர்கள் கூறினார்கள்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் சென்றேன். அவர்கள் ஸம்ஸம் கிணற்றிலிருந்து நீர் இறைத்துக் கொண்டிருந்தார்கள். அவர்களின் ஆடையின் நுனி ஸம்ஸம் நீரால் நனைந்திருந்தது. நான் அவர்களிடம், 'மக்கள் விதியைப் (கத்ர்) பற்றிப் பேசுகிறார்கள் (மறுக்கிறார்கள்)' என்றேன். அவர்கள், 'உண்மையாகவே அவர்கள் அவ்வாறு செய்கிறார்களா?' என்று கேட்டார்கள். நான், 'ஆம்' என்றேன். அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் மீது ஆணையாக! இந்த வசனம் அவர்களைப் பற்றி மட்டுமே அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُسْحَبُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">ذُوقُواْ</span> <span class=\"quran-arabic-font text-success\">مَسَّ</span> <span class=\"quran-arabic-font text-success\">سَقَرَ</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span><br />\r\n<br />\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) அவர்கள் இந்த உம்மத்தின் மிக மோசமானவர்கள். அவர்களில் எவரேனும் நோய்வாய்ப்பட்டால் நலம் விசாரிக்கச் செல்லாதீர்கள்; அவர்களில் எவரேனும் இறந்துவிட்டால் ஜனாஸா தொழுகை நடத்தாதீர்கள். அவர்களில் ஒருவரை நான் நேரில் கண்டால், எனது இந்த இரு விரல்களால் அவரது கண்களைப் பிடுங்கி விடுவேன்'.\" இமாம் அஹ்மத் அவர்கள் நாஃபிஃ வழியாகப் பதிவுசெய்துள்ளார்கள்: \"அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களுக்கு ஷாம் பகுதியில் ஒரு நண்பர் இருந்தார். அவர் இவருக்குக் கடிதம் எழுதுவது வழக்கம். அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அவருக்கு இவ்வாறு எழுதினார்கள்: 'நீர் விதியைப் (கத்ர்) பற்றிப் பேசத் தொடங்கியுள்ளதாக எனக்குத் தகவல் கிடைத்துள்ளது. எனவே, இனி எனக்குக் கடிதம் எழுதத் துணியாதீர். ஏனெனில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறக் கேட்டுள்ளேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">سَيَكُونُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">أَقْوَامٌ</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُونَ</span> <span class=\"quran-arabic-font text-success\">بِالْقَدَر</span>»<br />\r\n<br />\r\n(என் உம்மத்தில் விதியைப் (கத்ர்) பொய்யாக்கும் சில கூட்டத்தினர் தோன்றுவார்கள்.)\" அபூதாவூத் இந்த ஹதீஸை அஹ்மத் பின் ஹன்பல் வழியாகப் பதிவு செய்துள்ளார். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">بِقَدَرٍ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">الْعَجْزُ</span> <span class=\"quran-arabic-font text-success\">وَالْكَيْسُ</span>»<br />\r\n<br />\r\n(இயலாமை (சோம்பல்) மற்றும் புத்திசாலித்தனம் உட்பட ஒவ்வொன்றும் விதியின்படியே நடக்கின்றன.) முஸ்லிம் இமாம் மாலிக் அவர்களின் அறிவிப்பாளர் தொடர் வழியாக இந்த ஹதீஸைப் பதிவுசெய்துள்ளார். மற்றொரு ஆதாரப்பூர்வமான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اسْتَعِنْ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَعْجَزْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَكَ</span> <span class=\"quran-arabic-font text-success\">أَمْرٌ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span>: <span class=\"quran-arabic-font text-success\">قَدَّرَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">شَاءَ</span> <span class=\"quran-arabic-font text-success\">فَعَلَ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَقُلْ</span>: <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنِّي</span> <span class=\"quran-arabic-font text-success\">فَعَلْتُ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">كَذَا،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">تَفْتَحُ</span> <span class=\"quran-arabic-font text-success\">عَمَلَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَان</span>»<br />\r\n<br />\r\n(அல்லாஹ்விடம் உதவி தேடுங்கள், தளர்ந்துவிடாதீர்கள். உங்களுக்கு ஏதேனும் பாதிப்பு ஏற்பட்டால், \"அல்லாஹ் இதை விதித்துவிட்டான், அவன் நாடியதைச் செய்தான்\" என்று சொல்லுங்கள். மாறாக, \"நான் மட்டும் இப்படிச் செய்திருந்தால், அப்படி நடந்திருக்குமே\" என்று சொல்லாதீர்கள். ஏனெனில் \"இருந்தால்\" (if) என்ற சொல் ஷைத்தானின் செயலுக்கு வழிவகுக்கும்.) இப்னு அப்பாஸ் (ரழி) அவர்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறிய ஹதீஸ் ஒன்றில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَاعْلَمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">الْأُمَّةَ</span> <span class=\"quran-arabic-font text-success\">لَوِ</span> <span class=\"quran-arabic-font text-success\">اجْتَمَعُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَنْفَعُوكَ</span> <span class=\"quran-arabic-font text-success\">بِشَيْءٍ،</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبْهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَنْفَعُوكَ،</span> <span class=\"quran-arabic-font text-success\">وَلَوِ</span> <span class=\"quran-arabic-font text-success\">اجْتَمَعُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَضُرُّوكَ</span> <span class=\"quran-arabic-font text-success\">بِشَيْءٍ،</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَكْتُبْهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَضُرُّوكَ،</span> <span class=\"quran-arabic-font text-success\">جَفَّتِ</span> <span class=\"quran-arabic-font text-success\">الْأَقْلَامُ</span> <span class=\"quran-arabic-font text-success\">وَطُوِيَتِ</span> <span class=\"quran-arabic-font text-success\">الصُّحُف</span>»<br />\r\n<br />\r\n(அறிந்துகொள்! இந்த உம்மத்தினர் அனைவரும் ஒன்று சேர்ந்து உனக்கு ஒரு நன்மையைச் செய்ய நாடினாலும், அல்லாஹ் உனக்கு எழுதியதைத் தவிர வேறெந்த நன்மையையும் அவர்களால் செய்துவிட முடியாது. அதேபோல், அவர்கள் அனைவரும் ஒன்று சேர்ந்து உனக்கு ஒரு தீங்கை இழைக்க நாடினாலும், அல்லாஹ் உனக்கு விதித்ததைத் தவிர வேறெந்தத் தீங்கையும் அவர்களால் இழைக்க முடியாது. எழுதுகோல்கள் காய்ந்துவிட்டன; ஏடுகள் சுருட்டப்பட்டுவிட்டன.) இமாம் அஹ்மத் அவர்கள் உபாதா பின் அல்-வலீத் பின் உபாதா வழியாகப் பதிவுசெய்துள்ளார்கள்: \"உபாதா (ரழி) அவர்கள் நோய்வாய்ப்பட்டிருந்தபோது நான் அவர்களிடம் சென்றேன். அவர்கள் மரணிக்கக்கூடும் என்று நான் கருதியதால், 'என் தந்தையே! எங்களுக்கு அறிவுரை கூறுங்கள்' என்றேன். அதற்கு அவர்கள், 'என்னைச் சற்று அமர வையுங்கள்' என்று கூறி அமர்ந்த பின், 'என் மகனே! விதியின் (கத்ர்) நன்மை மற்றும் தீமைகளை நீ முழுமையாக நம்பும் வரை, ஈமானின் (நம்பிக்கையின்) சுவையை நீ உணர முடியாது; அல்லாஹ்வைப் பற்றிய உண்மையான அறிவையும் பெற முடியாது' என்றார்கள். நான், 'தந்தையே! விதியின் நன்மை தீமைகளை நான் எப்படி அறிந்துகொள்வது?' என்று கேட்டேன். அதற்கு அவர்கள், 'உனக்குக் கிடைக்காமல் போனது உனக்குக் கிடைத்திருக்காது என்றும், உனக்கு நேர்ந்தது உனக்கு நேராமல் இருந்திருக்காது என்றும் நீ உறுதியாக நம்ப வேண்டும். மகனே! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதை நான் கேட்டுள்ளேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْقَلَمَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">اكْتُبْ،</span> <span class=\"quran-arabic-font text-success\">فَجَرَى</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">كَائِنٌ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் முதன்முதலில் படைத்தது எழுதுகோலைத்தான். பிறகு அதற்கு, 'எழுது!' என்று கட்டளையிட்டான். உடனே அந்த எழுதுகோல் மறுமை நாள் வரை நிகழவிருப்பவை அனைத்தையும் எழுதியது.) மகனே! இந்த நம்பிக்கையில்லாமல் நீ மரணித்தால், நீ நரக நெருப்பில் நுழைவாய்' என்றார்கள்.\" திர்மிதி இதை பதிவு செய்து \"ஹஸன் ஸஹீஹ் ஃகரீப்\" எனக் குறிப்பிட்டுள்ளார். ஸஹீஹ் முஸ்லிமில் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">كَتَبَ</span> <span class=\"quran-arabic-font text-success\">مَقَادِيرَ</span> <span class=\"quran-arabic-font text-success\">الْخَلْقِ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقَ</span> <span class=\"quran-arabic-font text-success\">السَّموَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بِخَمْسِينَ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">سَنَة</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே படைப்புகளின் விதிகளைப் பதிவு செய்துவிட்டான்.) இப்னு வஹ்ப் அவர்கள் பின்வருமாறு கூடுதலாகக் குறிப்பிட்டுள்ளார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">عَرْشُهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمَآءِ</span><br />\r\n<br />\r\n(அப்போது அவனது அர்ஷ் தண்ணீரின் மீது இருந்தது.) (<a href=\"qurandisp.php?sura=11&ayah=7\" class=\"link\">11:7</a>) திர்மிதி இதைப் பதிவுசெய்து \"ஹஸன் ஸஹீஹ் ஃகரீப்\" என்று கூறியுள்ளார்.<br />\r\n<br />\r\n<strong>அல்லாஹ்வின் எச்சரிக்கைகள் குறித்து எச்சரிக்கையாக இருத்தல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">وَحِدَةٌ</span> <span class=\"quran-arabic-font text-success\">كَلَمْحٍ</span> <span class=\"quran-arabic-font text-success\">بِالْبَصَرِ</span><br />\r\n<br />\r\n(நமது கட்டளை கண் சிமிட்டுவதைப் போல ஒரே ஒரு முறைதான்.) படைப்புகளின் மீது அவனது விதி எவ்வாறு செயல்படுத்தப்படுகிறது என்பதை அல்லாஹ் நமக்கு அறிவிக்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">وَحِدَةٌ</span><br />\r\n<br />\r\n(நமது கட்டளை ஒன்றே ஒன்றுதான்), அதாவது நாம் ஒரு விஷயத்திற்கு ஒரு முறை மட்டுமே கட்டளையிடுகிறோம், அதை மீண்டும் சொல்லத் தேவையில்லை. நாம் எதை நாடுகிறோமோ அது ஒரு கணமும் தாமதமின்றி கண் சிமிட்டும் நேரத்தை விட வேகமாக நிகழ்ந்துவிடும். அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">أَشْيَاعَكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக உங்களைப் போன்றவர்களை (முந்தைய சமுதாயங்களை) நாம் அழித்துள்ளோம்), அதாவது தூதர்களைப் பொய்யாக்கிய முந்தைய சமுதாயங்களை நாம் அழித்தோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مُّدَّكِرٍ</span><br />\r\n<br />\r\n(அப்படியானால் படிப்பினை பெறுவோர் உண்டா?), அதாவது அல்லாஹ் அவர்களுக்கு விதித்த அவமானத்தையும் வேதனையையும் நினைவுகூர்ந்து யாராவது எச்சரிக்கை அடைவார்களா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحِيلَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشْتَهُونَ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">فُعِلَ</span> <span class=\"quran-arabic-font text-success\">بِأَشْيَـعِهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span><br />\r\n<br />\r\n(அவர்களுக்கும் அவர்கள் விரும்பியவற்றுக்கும் இடையே ஒரு திரை ஏற்படுத்தப்படும், இதற்கு முன் இருந்த அவர்களைப் போன்றவர்களுக்குச் செய்யப்பட்டது போலவே.) (<a href=\"qurandisp.php?sura=34&ayah=54\" class=\"link\">34:54</a>) அல்லாஹ்வின் கூற்று,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">فَعَلُوهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الزُّبُرِ</span><br />\r\n<br />\r\n(அவர்கள் செய்த ஒவ்வொன்றும் அஸ்-ஸுபுரில் (ஏடுகளில்) பதிவாகியுள்ளது.) அதாவது அவர்கள் செய்த அனைத்தும் வானவர்களிடம் (அலை) ஒப்படைக்கப்பட்டுள்ள பதிவேடுகளில் பதிவு செய்யப்பட்டுள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">صَغِيرٍ</span> <span class=\"quran-arabic-font text-success\">وَكَبِيرٍ</span><br />\r\n<br />\r\n(சிறியதோ பெரியதோ ஒவ்வொன்றும்), அதாவது அவர்களின் செயல்கள் அனைத்தும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُّسْتَطَرٌ</span><br />\r\n<br />\r\n(எழுதப்பட்டுள்ளது.) அவர்கள் செய்யும் ஒவ்வொன்றும் அவர்களின் வினைப் பதிவேட்டில் குறிக்கப்பட்டுள்ளது; அது சிறியதோ பெரியதோ எதையும் விட்டுவைக்காமல் பதிவுசெய்து கணக்கிட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عَائِشَةُ</span> <span class=\"quran-arabic-font text-success\">إِيَّاكِ</span> <span class=\"quran-arabic-font text-success\">وَمُحَقَّرَاتِ</span> <span class=\"quran-arabic-font text-success\">الذُّنُوبِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">طَالِبًا</span>»<br />\r\n<br />\r\n(ஆயிஷாவே! அற்பமானவை எனக் கருதப்படும் பாவங்கள் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில் அவற்றைக் கண்காணிக்க அல்லாஹ்வினால் நியமிக்கப்பட்ட ஒருவர் இருக்கிறார்.) நஸாயீ மற்றும் இப்னு மாஜாவும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<strong>இறையச்சம் (தக்வா) உடையவர்களுக்கு நற்முடிவு</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَنَهَرٍ</span><br />\r\n<br />\r\n(நிச்சயமாக தக்வா உடையவர்கள் சுவனச் சோலைகளிலும் ஆறுகளிலும் இருப்பார்கள்.) இது நரக நெருப்பில் முகங்கள் குப்புற இழுத்துச் செல்லப்பட்டு அவமானத்தையும் வேதனையையும் அனுபவிக்கும் பாவியரின் முடிவுக்கு முற்றிலும் மாறானது. அல்லாஹ் கூறினான்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مَقْعَدِ</span> <span class=\"quran-arabic-font text-success\">صِدْقٍ</span><br />\r\n<br />\r\n(உண்மையான இருக்கையில்), அல்லாஹ்வின் கண்ணியமான இல்லத்தில், அவனது திருப்தி, அருட்கொடைகள், தாராள குணம் மற்றும் கருணை ஆகியவற்றால் சூழப்பட்ட நிலையில் அவர்கள் இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">مَلِيكٍ</span> <span class=\"quran-arabic-font text-success\">مُّقْتَدِرٍ</span><br />\r\n<br />\r\n(சர்வ வல்லமையுள்ள அரசனின் முன்னிலையில்.) அதாவது, அனைத்தையும் படைத்து அதன் விதியை நிர்ணயித்த மாபெரும் இறைவனின் அருகில் இருப்பார்கள். அவர்கள் எதைக் கேட்டாலும் விரும்பினாலும் அதை வழங்க அவன் ஆற்றல் பெற்றவன். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْمُقْسِطُونَ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنَابِرَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نُورٍ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">يَمِينِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ</span> <span class=\"quran-arabic-font text-success\">وَكِلْتَا</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">يَمِينٌ،</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَعْدِلُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">حُكْمِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">وَلُوا</span>»<br />\r\n<br />\r\n(நிச்சயமாக நீதியாளர்கள் அர்-ரஹ்மானின் வலதுபுறத்தில் ஒளியாலான மேடைகளில் அல்லாஹ்விடம் இருப்பார்கள். அவனது இரு கைகளும் வலது கைகளே. அவர்கள் தங்கள் தீர்ப்புகளிலும், தங்கள் குடும்பத்தினரிடமும், தங்களுக்குப் பொறுப்பாக்கப்பட்டவர்களிடமும் நீதியுடனும் நேர்மையுடனும் நடப்பவர்கள்.) முஸ்லிம் மற்றும் நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஇத்துடன் ஸூரத்துல் கமர் (இக்தரபத்) தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. வெற்றியும் பாதுகாப்பும் அவனிடமிருந்தே வருகின்றன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"குற்றவாளிகளின் முடிவு\n\r\n\n\r\nகண்ணியமிக்க அல்லாஹ் கூறுகிறான், குற்றவாளிகள் சத்தியத்தை விட்டு வழிதவறி, தங்களின் சந்தேகங்கள் மற்றும் தடுமாற்றங்களின் காரணமாக குழப்பத்தில் மூழ்கியுள்ளனர். இந்தப் பண்பு, அனைத்து வகையான பிரிவுகளைச் சார்ந்த ஒவ்வொரு நிராகரிப்பாளருக்கும் மற்றும் மார்க்கத்தில் புதுமையைப் புகுத்துபவர்களுக்கும் பொருந்தும். கண்ணியமிக்க அல்லாஹ் கூறினான்,\n\r\n\n\r\nيَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ\n\r\n\n\r\n(அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்), அதாவது, அவர்கள் எவ்வாறு சந்தேகத்திலும் தயக்கத்திலும் மூழ்கியிருந்தார்களோ, அவ்வாறே நரக நெருப்பில் வீழ்வார்கள். அவர்கள் நேர்வழி தவறி வாழ்ந்ததைப் போலவே, தாங்கள் எங்கு கொண்டு செல்லப்படுகிறோம் என்பதை அறியாத நிலையில் முகங்கள் குப்புற இழுத்துச் செல்லப்படுவார்கள். அவர்கள் கண்டிக்கப்பட்டு இவ்வாறு கூறப்படுவார்கள்:\n\r\n\n\r\nذُوقُواْ مَسَّ سَقَرَ\n\r\n\n\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\")\n\r\n\n\r\nஅனைத்தும் விதியுடன் (கத்ருடன்) படைக்கப்பட்டுள்ளன\n\r\n\n\r\nஅல்லாஹ்வின் இக்கூற்று,\n\r\n\n\r\nإِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ\n\r\n\n\r\n(நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) என்பது மற்ற பல வசனங்களைப் போன்றதே ஆகும்:\n\r\n\n\r\nوَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا\n\r\n\n\r\n(அவன் ஒவ்வொரு பொருளையும் படைத்து, அதற்கென ஒரு விதியைத் துல்லியமாக நிர்ணயித்தான் (ஃபகத்தரஹு தக்தீரா).) (25:2) மற்றும்,\n\r\n\n\r\nسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى - الَّذِي خَلَقَ فَسَوَّى - وَالَّذِي قَدَّرَ فَهَدَى\n\r\n\n\r\n(உமது மிக உயர்ந்த இறைவனின் திருநாமத்தைத் துதிப்பீராக! அவன் (யாவற்றையும்) படைத்துச் சீராக்கினான். மேலும் அவன் (அனைத்தையும்) நிர்ணயித்து (கத்தர), பின்னர் வழிகாட்டினான்.) (87:1-3), அதாவது, அவன் ஒவ்வொரு பொருளின் மொத்த அளவையும் (கத்ரையும்) நிர்ணயித்து, படைப்புகளை அதன்பால் வழிநடத்தினான். படைப்புகள் உருவாக்கப்படுவதற்கு முன்பே அவற்றுக்கான விதிகளை அல்லாஹ் நிர்ணயித்துவிட்டான் என்பதற்கு சுன்னாவின் இமாம்கள் இந்த கண்ணியமிக்க வசனத்தை ஆதாரமாகக் கொள்கின்றனர். ஒவ்வொன்றும் நடப்பதற்கு முன்பே அது குறித்து அல்லாஹ் அறிந்திருந்தான்; மேலும் அவை நிகழ்வதற்கு முன்பே அனைத்தையும் பதிவு செய்துவிட்டான். ஸஹாபாக்களின் (ரழி) இறுதிக் காலத்தில் தோன்றிய 'கத்ரிய்யா' (விதியை மறுப்பவர்) பிரிவினரை மறுப்பதற்காக, அறிஞர்கள் இந்த வசனத்தையும், இது போன்ற பிற வசனங்களையும் ஹதீஸ்களையும் பயன்படுத்தினார்கள். இக்கருத்தைப் பற்றி ஸஹீஹ் அல்-புகாரியின் ஈமான் (நம்பிக்கை) அத்தியாயத்திற்கான எனது விளக்கவுரையில் விரிவாகக் குறிப்பிட்டுள்ளேன். இந்த வசனம் தொடர்பான சில ஹதீஸ்களை இங்கே குறிப்பிடுகிறேன். இமாம் அஹ்மத் அவர்கள் அபூஹுரைரா (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: \"குறைஷி இணைவைப்பாளர்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து விதியைப் (கத்ர்) பற்றி விவாதித்து அதை மறுத்தார்கள். அப்போது இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nيَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ - إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ\n\r\n\n\r\n(அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்: \"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.)\" முஸ்லிம், திர்மிதி மற்றும் இப்னு மாஜா ஆகியோரும் இந்த ஹதீஸைப் பதிவுசெய்துள்ளனர். அல்-பஸ்ஸார் அவர்கள் அம்ர் பின் ஷுஐப் தனது தந்தை மற்றும் பாட்டனார் வழியாகக் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: \"இந்த வசனங்கள் விதியை (கத்ர்) மறுப்பவர்களைப் பற்றி அருளப்பட்டன:\n\r\n\n\r\nإِنَّ الْمُجْرِمِينَ فِي ضَلَالٍ وَسُعُرٍ - يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ\n\r\n\n\r\nإِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ\n\r\n\n\r\n(நிச்சயமாக, குற்றவாளிகள் வழிகேட்டிலும் நரக நெருப்பிலுமே இருப்பார்கள். அவர்கள் தங்கள் முகங்களால் நரக நெருப்பில் இழுத்துச் செல்லப்படும் நாளில்: \"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.)\" இப்னு அபீ ஹாதிம் அவர்கள் ஸுராரா தனது தந்தை வழியாகக் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nيَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ - إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ\n\r\n\n\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) பின்னர் கூறினார்கள்:\n\r\n\n\r\n«نَزَلَتْ فِي أُنَاسٍ مِنْ أُمَّتِي يَكُونُونَ فِي آخِرِ الزَّمَانِ يُكَذِّبُونَ بِقَدَرِ الله»\n\r\n\n\r\n(இந்த வசனங்கள் என் உம்மத்தைச் சேர்ந்த சிலரைப் பற்றி அருளப்பட்டன. அவர்கள் இறுதி காலத்தில் தோன்றி அல்லாஹ்வின் விதியைப் (கத்ர்) பொய்யாக்குவார்கள்.) அதாஃ பின் அபீ ரபாஹ் அவர்கள் கூறினார்கள்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் சென்றேன். அவர்கள் ஸம்ஸம் கிணற்றிலிருந்து நீர் இறைத்துக் கொண்டிருந்தார்கள். அவர்களின் ஆடையின் நுனி ஸம்ஸம் நீரால் நனைந்திருந்தது. நான் அவர்களிடம், 'மக்கள் விதியைப் (கத்ர்) பற்றிப் பேசுகிறார்கள் (மறுக்கிறார்கள்)' என்றேன். அவர்கள், 'உண்மையாகவே அவர்கள் அவ்வாறு செய்கிறார்களா?' என்று கேட்டார்கள். நான், 'ஆம்' என்றேன். அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ்வின் மீது ஆணையாக! இந்த வசனம் அவர்களைப் பற்றி மட்டுமே அருளப்பட்டது:\n\r\n\n\r\nيَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُواْ مَسَّ سَقَرَ - إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ\n\r\n\n\r\n(\"நரகத்தின் தீண்டுதலைச் சுவைத்துப் பாருங்கள்!\" நிச்சயமாக, நாம் ஒவ்வொரு பொருளையும் ஒரு விதியின்படியே (கத்ருடன்) படைத்துள்ளோம்.) அவர்கள் இந்த உம்மத்தின் மிக மோசமானவர்கள். அவர்களில் எவரேனும் நோய்வாய்ப்பட்டால் நலம் விசாரிக்கச் செல்லாதீர்கள்; அவர்களில் எவரேனும் இறந்துவிட்டால் ஜனாஸா தொழுகை நடத்தாதீர்கள். அவர்களில் ஒருவரை நான் நேரில் கண்டால், எனது இந்த இரு விரல்களால் அவரது கண்களைப் பிடுங்கி விடுவேன்'.\" இமாம் அஹ்மத் அவர்கள் நாஃபிஃ வழியாகப் பதிவுசெய்துள்ளார்கள்: \"அப்துல்லாஹ் பின் உமர் (ரழி) அவர்களுக்கு ஷாம் பகுதியில் ஒரு நண்பர் இருந்தார். அவர் இவருக்குக் கடிதம் எழுதுவது வழக்கம். அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் அவருக்கு இவ்வாறு எழுதினார்கள்: 'நீர் விதியைப் (கத்ர்) பற்றிப் பேசத் தொடங்கியுள்ளதாக எனக்குத் தகவல் கிடைத்துள்ளது. எனவே, இனி எனக்குக் கடிதம் எழுதத் துணியாதீர். ஏனெனில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறக் கேட்டுள்ளேன்:\n\r\n\n\r\n«سَيَكُونُ فِي أُمَّتِي أَقْوَامٌ يُكَذِّبُونَ بِالْقَدَر»\n\r\n\n\r\n(என் உம்மத்தில் விதியைப் (கத்ர்) பொய்யாக்கும் சில கூட்டத்தினர் தோன்றுவார்கள்.)\" அபூதாவூத் இந்த ஹதீஸை அஹ்மத் பின் ஹன்பல் வழியாகப் பதிவு செய்துள்ளார். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் உமர் (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كُلُّ شَيْءٍ بِقَدَرٍ حَتَّى الْعَجْزُ وَالْكَيْسُ»\n\r\n\n\r\n(இயலாமை (சோம்பல்) மற்றும் புத்திசாலித்தனம் உட்பட ஒவ்வொன்றும் விதியின்படியே நடக்கின்றன.) முஸ்லிம் இமாம் மாலிக் அவர்களின் அறிவிப்பாளர் தொடர் வழியாக இந்த ஹதீஸைப் பதிவுசெய்துள்ளார். மற்றொரு ஆதாரப்பூர்வமான ஹதீஸில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اسْتَعِنْ بِاللهِ وَلَا تَعْجَزْ، فَإِنْ أَصَابَكَ أَمْرٌ فَقُلْ: قَدَّرَ اللهُ وَمَا شَاءَ فَعَلَ، وَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ كَذَا لَكَانَ كَذَا، فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَان»\n\r\n\n\r\n(அல்லாஹ்விடம் உதவி தேடுங்கள், தளர்ந்துவிடாதீர்கள். உங்களுக்கு ஏதேனும் பாதிப்பு ஏற்பட்டால், \"அல்லாஹ் இதை விதித்துவிட்டான், அவன் நாடியதைச் செய்தான்\" என்று சொல்லுங்கள். மாறாக, \"நான் மட்டும் இப்படிச் செய்திருந்தால், அப்படி நடந்திருக்குமே\" என்று சொல்லாதீர்கள். ஏனெனில் \"இருந்தால்\" (if) என்ற சொல் ஷைத்தானின் செயலுக்கு வழிவகுக்கும்.) இப்னு அப்பாஸ் (ரழி) அவர்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறிய ஹதீஸ் ஒன்றில்:\n\r\n\n\r\n«وَاعْلَمْ أَنَّ الْأُمَّةَ لَوِ اجْتَمَعُوا عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ، لَمْ يَكْتُبْهُ اللهُ لَكَ لَمْ يَنْفَعُوكَ، وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ، لَمْ يَكْتُبْهُ اللهُ عَلَيْكَ لَمْ يَضُرُّوكَ، جَفَّتِ الْأَقْلَامُ وَطُوِيَتِ الصُّحُف»\n\r\n\n\r\n(அறிந்துகொள்! இந்த உம்மத்தினர் அனைவரும் ஒன்று சேர்ந்து உனக்கு ஒரு நன்மையைச் செய்ய நாடினாலும், அல்லாஹ் உனக்கு எழுதியதைத் தவிர வேறெந்த நன்மையையும் அவர்களால் செய்துவிட முடியாது. அதேபோல், அவர்கள் அனைவரும் ஒன்று சேர்ந்து உனக்கு ஒரு தீங்கை இழைக்க நாடினாலும், அல்லாஹ் உனக்கு விதித்ததைத் தவிர வேறெந்தத் தீங்கையும் அவர்களால் இழைக்க முடியாது. எழுதுகோல்கள் காய்ந்துவிட்டன; ஏடுகள் சுருட்டப்பட்டுவிட்டன.) இமாம் அஹ்மத் அவர்கள் உபாதா பின் அல்-வலீத் பின் உபாதா வழியாகப் பதிவுசெய்துள்ளார்கள்: \"உபாதா (ரழி) அவர்கள் நோய்வாய்ப்பட்டிருந்தபோது நான் அவர்களிடம் சென்றேன். அவர்கள் மரணிக்கக்கூடும் என்று நான் கருதியதால், 'என் தந்தையே! எங்களுக்கு அறிவுரை கூறுங்கள்' என்றேன். அதற்கு அவர்கள், 'என்னைச் சற்று அமர வையுங்கள்' என்று கூறி அமர்ந்த பின், 'என் மகனே! விதியின் (கத்ர்) நன்மை மற்றும் தீமைகளை நீ முழுமையாக நம்பும் வரை, ஈமானின் (நம்பிக்கையின்) சுவையை நீ உணர முடியாது; அல்லாஹ்வைப் பற்றிய உண்மையான அறிவையும் பெற முடியாது' என்றார்கள். நான், 'தந்தையே! விதியின் நன்மை தீமைகளை நான் எப்படி அறிந்துகொள்வது?' என்று கேட்டேன். அதற்கு அவர்கள், 'உனக்குக் கிடைக்காமல் போனது உனக்குக் கிடைத்திருக்காது என்றும், உனக்கு நேர்ந்தது உனக்கு நேராமல் இருந்திருக்காது என்றும் நீ உறுதியாக நம்ப வேண்டும். மகனே! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதை நான் கேட்டுள்ளேன்:\n\r\n\n\r\n«إِنَّ أَوَّلَ مَا خَلَقَ اللهُ الْقَلَمَ، ثُمَّ قَالَ لَهُ: اكْتُبْ، فَجَرَى فِي تِلْكَ السَّاعَةِ بِمَا هُوَ كَائِنٌ إِلَى يَوْمِ الْقِيَامَة»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் முதன்முதலில் படைத்தது எழுதுகோலைத்தான். பிறகு அதற்கு, 'எழுது!' என்று கட்டளையிட்டான். உடனே அந்த எழுதுகோல் மறுமை நாள் வரை நிகழவிருப்பவை அனைத்தையும் எழுதியது.) மகனே! இந்த நம்பிக்கையில்லாமல் நீ மரணித்தால், நீ நரக நெருப்பில் நுழைவாய்' என்றார்கள்.\" திர்மிதி இதை பதிவு செய்து \"ஹஸன் ஸஹீஹ் ஃகரீப்\" எனக் குறிப்பிட்டுள்ளார். ஸஹீஹ் முஸ்லிமில் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ كَتَبَ مَقَادِيرَ الْخَلْقِ قَبْلَ أَنْ يَخْلُقَ السَّموَاتِ وَالْأَرْضَ بِخَمْسِينَ أَلْفَ سَنَة»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் வானங்களையும் பூமியையும் படைப்பதற்கு ஐம்பதாயிரம் ஆண்டுகளுக்கு முன்பே படைப்புகளின் விதிகளைப் பதிவு செய்துவிட்டான்.) இப்னு வஹ்ப் அவர்கள் பின்வருமாறு கூடுதலாகக் குறிப்பிட்டுள்ளார்:\n\r\n\n\r\nوَكَانَ عَرْشُهُ عَلَى الْمَآءِ\n\r\n\n\r\n(அப்போது அவனது அர்ஷ் தண்ணீரின் மீது இருந்தது.) (11:7) திர்மிதி இதைப் பதிவுசெய்து \"ஹஸன் ஸஹீஹ் ஃகரீப்\" என்று கூறியுள்ளார்.\n\r\n\n\r\nஅல்லாஹ்வின் எச்சரிக்கைகள் குறித்து எச்சரிக்கையாக இருத்தல்\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nوَمَآ أَمْرُنَآ إِلاَّ وَحِدَةٌ كَلَمْحٍ بِالْبَصَرِ\n\r\n\n\r\n(நமது கட்டளை கண் சிமிட்டுவதைப் போல ஒரே ஒரு முறைதான்.) படைப்புகளின் மீது அவனது விதி எவ்வாறு செயல்படுத்தப்படுகிறது என்பதை அல்லாஹ் நமக்கு அறிவிக்கிறான்.\n\r\n\n\r\nوَمَآ أَمْرُنَآ إِلاَّ وَحِدَةٌ\n\r\n\n\r\n(நமது கட்டளை ஒன்றே ஒன்றுதான்), அதாவது நாம் ஒரு விஷயத்திற்கு ஒரு முறை மட்டுமே கட்டளையிடுகிறோம், அதை மீண்டும் சொல்லத் தேவையில்லை. நாம் எதை நாடுகிறோமோ அது ஒரு கணமும் தாமதமின்றி கண் சிமிட்டும் நேரத்தை விட வேகமாக நிகழ்ந்துவிடும். அல்லாஹ் கூறினான்,\n\r\n\n\r\nوَلَقَدْ أَهْلَكْنَا أَشْيَاعَكُمْ\n\r\n\n\r\n(நிச்சயமாக உங்களைப் போன்றவர்களை (முந்தைய சமுதாயங்களை) நாம் அழித்துள்ளோம்), அதாவது தூதர்களைப் பொய்யாக்கிய முந்தைய சமுதாயங்களை நாம் அழித்தோம்.\n\r\n\n\r\nفَهَلْ مِن مُّدَّكِرٍ\n\r\n\n\r\n(அப்படியானால் படிப்பினை பெறுவோர் உண்டா?), அதாவது அல்லாஹ் அவர்களுக்கு விதித்த அவமானத்தையும் வேதனையையும் நினைவுகூர்ந்து யாராவது எச்சரிக்கை அடைவார்களா?\n\r\n\n\r\nوَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَـعِهِم مِّن قَبْلُ\n\r\n\n\r\n(அவர்களுக்கும் அவர்கள் விரும்பியவற்றுக்கும் இடையே ஒரு திரை ஏற்படுத்தப்படும், இதற்கு முன் இருந்த அவர்களைப் போன்றவர்களுக்குச் செய்யப்பட்டது போலவே.) (34:54) அல்லாஹ்வின் கூற்று,\n\r\n\n\r\nوَكُلُّ شَيْءٍ فَعَلُوهُ فِي الزُّبُرِ\n\r\n\n\r\n(அவர்கள் செய்த ஒவ்வொன்றும் அஸ்-ஸுபுரில் (ஏடுகளில்) பதிவாகியுள்ளது.) அதாவது அவர்கள் செய்த அனைத்தும் வானவர்களிடம் (அலை) ஒப்படைக்கப்பட்டுள்ள பதிவேடுகளில் பதிவு செய்யப்பட்டுள்ளன.\n\r\n\n\r\nوَكُلُّ صَغِيرٍ وَكَبِيرٍ\n\r\n\n\r\n(சிறியதோ பெரியதோ ஒவ்வொன்றும்), அதாவது அவர்களின் செயல்கள் அனைத்தும்,\n\r\n\n\r\nمُّسْتَطَرٌ\n\r\n\n\r\n(எழுதப்பட்டுள்ளது.) அவர்கள் செய்யும் ஒவ்வொன்றும் அவர்களின் வினைப் பதிவேட்டில் குறிக்கப்பட்டுள்ளது; அது சிறியதோ பெரியதோ எதையும் விட்டுவைக்காமல் பதிவுசெய்து கணக்கிட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் ஆயிஷா (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا عَائِشَةُ إِيَّاكِ وَمُحَقَّرَاتِ الذُّنُوبِ، فَإِنَّ لَهَا مِنَ اللهِ طَالِبًا»\n\r\n\n\r\n(ஆயிஷாவே! அற்பமானவை எனக் கருதப்படும் பாவங்கள் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில் அவற்றைக் கண்காணிக்க அல்லாஹ்வினால் நியமிக்கப்பட்ட ஒருவர் இருக்கிறார்.) நஸாயீ மற்றும் இப்னு மாஜாவும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஇறையச்சம் (தக்வா) உடையவர்களுக்கு நற்முடிவு\n\r\n\n\r\nஅல்லாஹ் கூறினான்,\n\r\n\n\r\nإِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ\n\r\n\n\r\n(நிச்சயமாக தக்வா உடையவர்கள் சுவனச் சோலைகளிலும் ஆறுகளிலும் இருப்பார்கள்.) இது நரக நெருப்பில் முகங்கள் குப்புற இழுத்துச் செல்லப்பட்டு அவமானத்தையும் வேதனையையும் அனுபவிக்கும் பாவியரின் முடிவுக்கு முற்றிலும் மாறானது. அல்லாஹ் கூறினான்,\n\r\n\n\r\nفِي مَقْعَدِ صِدْقٍ\n\r\n\n\r\n(உண்மையான இருக்கையில்), அல்லாஹ்வின் கண்ணியமான இல்லத்தில், அவனது திருப்தி, அருட்கொடைகள், தாராள குணம் மற்றும் கருணை ஆகியவற்றால் சூழப்பட்ட நிலையில் அவர்கள் இருப்பார்கள்.\n\r\n\n\r\nعِندَ مَلِيكٍ مُّقْتَدِرٍ\n\r\n\n\r\n(சர்வ வல்லமையுள்ள அரசனின் முன்னிலையில்.) அதாவது, அனைத்தையும் படைத்து அதன் விதியை நிர்ணயித்த மாபெரும் இறைவனின் அருகில் இருப்பார்கள். அவர்கள் எதைக் கேட்டாலும் விரும்பினாலும் அதை வழங்க அவன் ஆற்றல் பெற்றவன். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாகப் பதிவுசெய்துள்ளார்கள்: நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الْمُقْسِطُونَ عِنْدَ اللهِ عَلَى مَنَابِرَ مِنْ نُورٍ عَنْ يَمِينِ الرَّحْمنِ وَكِلْتَا يَدَيْهِ يَمِينٌ، الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا»\n\r\n\n\r\n(நிச்சயமாக நீதியாளர்கள் அர்-ரஹ்மானின் வலதுபுறத்தில் ஒளியாலான மேடைகளில் அல்லாஹ்விடம் இருப்பார்கள். அவனது இரு கைகளும் வலது கைகளே. அவர்கள் தங்கள் தீர்ப்புகளிலும், தங்கள் குடும்பத்தினரிடமும், தங்களுக்குப் பொறுப்பாக்கப்பட்டவர்களிடமும் நீதியுடனும் நேர்மையுடனும் நடப்பவர்கள்.) முஸ்லிம் மற்றும் நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஇத்துடன் ஸூரத்துல் கமர் (இக்தரபத்) தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. வெற்றியும் பாதுகாப்பும் அவனிடமிருந்தே வருகின்றன."}}};})(self);
